export const DAILY_HADITH_POOL: DailyHadithEntry[] = [
  { arabic: "وَعَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسلم: «من وَجَدْتُمُوهُ يَعْمَلُ عَمَلَ قَوْمِ لُوطٍ فَاقْتُلُوا الْفَاعِلَ وَالْمَفْعُول بِهِ» . رَوَاهُ التِّرْمِذِيّ وَابْن مَاجَه", chapter: "Prescribed Punishments", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَهَذِهِ اَلزِّيَادَةُ فِي هَذَا اَلْحَدِيثِ عِنْدَ أَبِي دَاوُدَ مِنْ حَدِيثِ عَلِيٍّ دُونَ قَوْلِهِ: { اِسْتَطْلَقَ اَلْوِكَاءُ }  وَفِي كِلَا الْإِسْنَادَيْنِ ضَعْف ٌ  1‏ .‏‏1 ‏- حسن.‏ رواه أحمد (4/97)‏، وأبو داود (203)‏ وفي الأصل زيادة تفصيل.‏", chapter: "The Book of Purification", ref: "Bulugh Almaram · Unknown" },
  { arabic: "وعن أبى يعلى معقل بن يسار رضي الله عنه قال‏:‏ سمعت رسول الله صلى الله عليه وسلم‏:‏ يقول‏:‏ “ما من عبد يستر عليه الله رعية، يموت يوم يموت وهو غاش لرعيته، إلا حرم الله عليه الجنة” ‏(‏‏(‏متفق عليه‏)‏‏)‏ \n\n‏(‏‏(‏وفي رواية‏:‏ ‏\"‏فلم يحطها بنصحه لم يجد رائحة الجنة‏\"‏‏)‏‏)‏\n\n\nوفي رواية لمسلم‏:‏ ‏\"‏ما من أمير يلى أمور المسلمين، ثم لا يجهد لهم وينصح لهم، إلا لم يدخل معهم الجنة‏\"‏‏.‏", chapter: "The Book of Miscellany", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وعن ابن عمر رضي الله عنهما قال‏:‏ قال النبي صلى الله عليه وسلم ‏:‏ ‏\n\"‏أفرى الفرى أن يري الرجل عينيه ما لم تريا‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏ ‏\nومعناه يقول‏:‏ رأيت فيما لم يره‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، أَنَّ إِسْحَاقَ بْنَ مَنْصُورٍ، حَدَّثَهُمْ عَنْ حَمَّادِ بْنِ سَلَمَةَ، عَنْ رَجُلٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، - رضى الله عنها - عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ ‏.‏", chapter: "Purification (Kitab Al-Taharah)", ref: "Abudawud · Unknown" },
  { arabic: "عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَعَنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكَلَ الرِّبَا وَمُوَكِلَهُ وَكَاتِبَهُ وَشَاهِدَيْهِ وَقَالَ: «هُمْ سَوَاءٌ» . رَوَاهُ مُسلم", chapter: "Business Transactions", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا يَحْيَى بْنُ مَعِينٍ، حَدَّثَنَا حَفْصٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ مَنْ أَقَالَ مُسْلِمًا أَقَالَهُ اللَّهُ عَثْرَتَهُ ‏\"‏ ‏.‏", chapter: "Wages (Kitab Al-Ijarah)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَبَّادٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنِ الزُّهْرِيِّ، عَنْ سَالِمٍ، عَنْ أَبِيهِ، أَخْبَرَتْنِي حَفْصَةُ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ إِذَا أَضَاءَ لَهُ الْفَجْرُ صَلَّى رَكْعَتَيْنِ ‏.‏", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي بَكْرٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَجُلاً، اطَّلَعَ مِنْ بَعْضِ حُجَرِ النَّبِيِّ صلى الله عليه وسلم فَقَامَ إِلَيْهِ النَّبِيُّ صلى الله عليه وسلم بِمِشْقَصٍ ـ أَوْ بِمَشَاقِصَ ـ فَكَأَنِّي أَنْظُرُ إِلَيْهِ يَخْتِلُ الرَّجُلَ لِيَطْعُنَهُ‏.‏", chapter: "Asking Permission", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ يَقُولُ سَبَى النَّبِيُّ صلى الله عليه وسلم صَفِيَّةَ، فَأَعْتَقَهَا وَتَزَوَّجَهَا‏.‏ فَقَالَ ثَابِتٌ لأَنَسٍ مَا أَصْدَقَهَا قَالَ أَصْدَقَهَا نَفْسَهَا فَأَعْتَقَهَا‏.‏", chapter: "Military Expeditions led by the Prophet (pbuh) (Al-Maghaazi)", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا مَحْمُودُ بْنُ غَيْلاَنَ، قَالَ حَدَّثَنَا وَكِيعٌ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنْ إِبْرَاهِيمَ بْنِ عَبْدِ الأَعْلَى، عَنْ سُوَيْدِ بْنِ غَفَلَةَ، أَنَّ عُمَرَ، قَبَّلَ الْحَجَرَ وَالْتَزَمَهُ وَقَالَ رَأَيْتُ أَبَا الْقَاسِمِ صلى الله عليه وسلم بِكَ حَفِيًّا ‏.‏", chapter: "The Book of Hajj", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ نُمَيْرٍ، وَأَبُو أُسَامَةَ عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ، عَنْ خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ حَفْصِ بْنِ عَاصِمٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ إِنَّ الإِيمَانَ لَيَأْرِزُ إِلَى الْمَدِينَةِ كَمَا تَأْرِزُ الْحَيَّةُ إِلَى جُحْرِهَا ‏\"‏ ‏.‏", chapter: "Chapters on Hajj Rituals", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ مُحَمَّدٍ، حَدَّثَنَا وَكِيعٌ، عَنْ بَشِيرِ بْنِ مُهَاجِرٍ، عَنِ ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ يَجِيءُ الْقُرْآنُ يَوْمَ الْقِيَامَةِ كَالرَّجُلِ الشَّاحِبِ فَيَقُولُ أَنَا الَّذِي أَسْهَرْتُ لَيْلَكَ وَأَظْمَأْتُ نَهَارَكَ ‏\"‏ ‏.‏", chapter: "Etiquette", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا أَحْمَدُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ، حَدَّثَنَا أَبِي قَالَ، سَمِعْتُ الأَعْمَشَ، يُحَدِّثُ عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَعَنَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْوَاشِمَاتِ وَالْمُتَفَلِّجَاتِ وَالْمُتَنَمِّصَاتِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ عَزَّ وَجَلَّ ‏.‏", chapter: "The Book of Adornment", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنَا يُوسُفُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا حَجَّاجٌ، عَنْ شَرِيكٍ، عَنِ الْحُرِّ بْنِ صَيَّاحٍ، قَالَ سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ كَانَ النَّبِيُّ صلى الله عليه وسلم يَصُومُ ثَلاَثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏.‏", chapter: "The Book of Fasting", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ انْخَسَفَتِ الشَّمْسُ، فَصَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏\n\"‏ أُرِيتُ النَّارَ، فَلَمْ أَرَ مَنْظَرًا كَالْيَوْمِ قَطُّ أَفْظَعَ ‏\"‏‏.‏", chapter: "Prayers (Salat)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ سَعْدِ بْنِ عَمَّارٍ الْمُؤَذِّنِ، حَدَّثَنَا عُمَرُ بْنُ حَفْصٍ، عَنْ عَمَّارِ بْنِ سَعْدٍ، مُؤَذِّنِ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ أَمَرَ بِصَدَقَةِ الْفِطْرِ صَاعًا مِنْ تَمْرٍ أَوْ صَاعًا مِنْ شَعِيرٍ أَوْ صَاعًا مِنْ سُلْتٍ ‏.‏", chapter: "The Chapters Regarding Zakat", ref: "Ibnmajah · Unknown" },
  { arabic: "وَعَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَنْ يَبْرَحَ هَذَا الدِّينُ قَائِمًا يُقَاتِلُ عَلَيْهِ عِصَابَةٌ مِنَ الْمُسْلِمِينَ حَتَّى تقوم السَّاعَة» . رَوَاهُ مُسلم", chapter: "Jihad", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُلَيْمَانُ بْنُ كَثِيرٍ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذِهِ الْقِصَّةِ قَالَ فَأَبَى أَنْ يُخْبِرَهُ ‏.‏", chapter: "Model Behavior of the Prophet (Kitab Al-Sunnah)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرِو بْنِ دِينَارٍ، عَنْ طَاوُسٍ، عَنْ حُجْرٍ الْمَدَرِيِّ، عَنْ زَيْدِ بْنِ ثَابِتٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم جَعَلَ الْعُمْرَى لِلْوَارِثِ ‏.‏", chapter: "The Chapters on Gifts", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا حُسَيْنُ بْنُ عِيسَى، قَالَ حَدَّثَنَا يُونُسُ بْنُ مُحَمَّدٍ، قَالَ حَدَّثَنَا فُلَيْحُ بْنُ سُلَيْمَانَ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ عَمْرِو بْنِ حَزْمٍ، عَنْ عَبَّادِ بْنِ تَمِيمٍ، عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ‏.‏", chapter: "Ablutions (Wudu')", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَسْوَدُ بْنُ عَامِرٍ، عَنْ شَرِيكٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ أَبِي مَسْعُودٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ الْمُسْتَشَارُ مُؤْتَمَنٌ ‏\"‏ ‏.‏", chapter: "Etiquette", ref: "Ibnmajah · Unknown" },
  { arabic: "وَعَن ابْنيْ بُسرٍ السُّلَمِيَّين قَالَا: دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَدَّمْنَا زُبْدًا وَتَمْرًا وَكَانَ يُحِبُّ الزبدَ والتمرِ. رَوَاهُ أَبُو دَاوُد", chapter: "Foods", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَخْطُبُ عَلَى الْمِنْبَرِ يَقُولُ ‏\n\"‏ إِنَّكُمْ مُلاَقُو اللَّهِ حُفَاةً عُرَاةً غُرْلاً ‏\"‏‏.‏", chapter: "To make the Heart Tender (Ar-Riqaq)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا يَحْيَى بْنُ زَكَرِيَّاءَ بْنِ أَبِي زَائِدَةَ، عَنِ ابْنِ جُرَيْجٍ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، قَالَ ذَبَحَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ عَائِشَةَ بَقَرَةً يَوْمَ النَّحْرِ ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى، - يَعْنِي ابْنَ إِسْمَاعِيلَ - حَدَّثَنَا أَبَانُ، حَدَّثَنَا قَتَادَةُ، حَدَّثَنِي بَكْرُ بْنُ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا قَالَ ‏\"‏ فِيهِمَا خَبَثًا ‏\"‏ ‏.‏ قَالَ فِي الْمَوْضِعَيْنِ ‏\"‏ خَبَثًا ‏\"‏ ‏.‏", chapter: "Prayer (Kitab Al-Salat)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا الْوَلِيدُ بْنُ مُسْلِمٍ، عَنْ سَعِيدِ بْنِ سِنَانٍ، عَنْ أَبِي الزَّاهِرِيَّةِ، عَنْ أَبِي عِنَبَةَ الْخَوْلاَنِيِّ، أَنَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ كَانَ يَقْرَأُ فِي الْجُمُعَةِ بِـ ‏{سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى}‏ وَ ‏{هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ}‏ ‏.‏", chapter: "Establishing the Prayer and the Sunnah Regarding Them", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ مُحَمَّدٍ، حَدَّثَنَا وَكِيعٌ، عَنْ كَهْمَسِ بْنِ الْحَسَنِ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ مَا أَدْعُو قَالَ ‏\n\"‏ تَقُولِينَ اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏\"‏ ‏.‏", chapter: "Supplication", ref: "Ibnmajah · Unknown" },
  { arabic: "وَعَنِ ابْنِ عُمَرَ قَالَ: قَطَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ سَارِقٍ فِي مِجَنٍّ ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ", chapter: "Prescribed Punishments", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، وَعَبْدُ اللَّهِ بْنُ نُمَيْرٍ، قَالاَ حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\n\"‏ إِذَا كَفَّرَ الرَّجُلُ أَخَاهُ فَقَدْ بَاءَ بِهَا أَحَدُهُمَا ‏\"‏ ‏.‏", chapter: "The Book of Faith", ref: "Muslim · Unknown" },
  { arabic: "وَعَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الْيَمِينُ عَلَى نِيَّةِ الْمُسْتَحْلِفِ» . رَوَاهُ مُسلم", chapter: "Oaths and Vows", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا إِسْمَاعِيلُ قَالَ‏:‏ حَدَّثَنِي مَالِكٌ، عَنْ أَبِي الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ‏:‏ مِنْ شَرِّ النَّاسِ ذُو الْوَجْهَيْنِ، الَّذِي يَأْتِي هَؤُلاَءِ بِوَجْهٍ، وَهَؤُلاَءِ بِوَجْهٍ‏.‏", chapter: "Meddling and Harshness", ref: "Aladab Almufrad · Unknown" },
  { arabic: "عن جابر رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏لا يسأل بوجه الله إلا الجنة‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَعَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ شِرَاءِ التَّمْرِ بِالرُّطَبِ فَقَالَ: «أَيَنْقُصُ الرُّطَبُ إِذَا يَبِسَ؟» فَقَالَ: نَعَمْ فَنَهَاهُ عَنْ ذَلِكَ. رَوَاهُ مَالِكٌ وَالتِّرْمِذِيُّ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَه", chapter: "Business Transactions", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "أَخْبَرَنِي زِيَادُ بْنُ أَيُّوبَ، قَالَ حَدَّثَنَا عَلِيُّ بْنُ غُرَابٍ، قَالَ حَدَّثَنَا بَيْهَسُ بْنُ فَهْدَانَ، قَالَ أَنْبَأَنَا أَبُو شَيْخٍ، قَالَ سَمِعْتُ ابْنَ عُمَرَ، قَالَ نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ لُبْسِ الذَّهَبِ إِلاَّ مُقَطَّعًا ‏.‏ قَالَ أَبُو عَبْدِ الرَّحْمَنِ حَدِيثُ النَّضْرِ أَشْبَهُ بِالصَّوَابِ وَاللَّهُ تَعَالَى أَعْلَمُ ‏.‏", chapter: "The Book of Adornment", ref: "Nasai · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَائِشَةَ، سُئِلَتْ عَنْ غُسْلِ الْمَرْأَةِ، مِنَ الْجَنَابَةِ فَقَالَتْ لِتَحْفِنْ عَلَى رَأْسِهَا ثَلاَثَ حَفَنَاتٍ مِنَ الْمَاءِ وَلْتَضْغَثْ رَأْسَهَا بِيَدَيْهَا ‏.‏", chapter: "Purity", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا إِسْمَاعِيلُ قَالَ‏:‏ حَدَّثَنِي سُلَيْمَانُ، عَنْ مُعَاوِيَةَ بْنِ أَبِي مُزَرِّدٍ، عَنْ يَزِيدَ بْنِ رُومَانَ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ‏:‏ الرَّحِمُ شُجْنَةٌ مِنَ اللهِ، مَنْ وَصَلَهَا وَصَلَهُ اللَّهُ، وَمَنْ قَطَعَهَا قَطَعَهُ اللَّهُ‏.‏", chapter: "Ties of Kinship", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ عَيَّاشٍ، عَنْ مُحَمَّدِ بْنِ زِيَادٍ، عَنْ أَبِي أُمَامَةَ، قَالَ أَمَرَنَا نَبِيُّنَا ـ صلى الله عليه وسلم ـ أَنْ نُفْشِيَ السَّلاَمَ ‏.‏", chapter: "Etiquette", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ سُمَىٍّ، مَوْلَى أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ عَنْ أَبِي صَالِحٍ السَّمَّانِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ الْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا وَالْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلاَّ الْجَنَّةُ ‏\"‏ ‏.‏", chapter: "Hajj", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا هُشَيْمٌ، عَنْ حُصَيْنٍ، عَنْ أَبِي وَائِلٍ، عَنْ حُذَيْفَةَ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا قَامَ لِيَتَهَجَّدَ يَشُوصُ فَاهُ بِالسِّوَاكِ ‏.‏", chapter: "The Book of Purification", ref: "Muslim · Unknown" },
  { arabic: "وَحَدَّثَنَاهُ أَبُو كُرَيْبٍ، حَدَّثَنَا ابْنُ بِشْرٍ، عَنْ مِسْعَرٍ، حَدَّثَنِي بُكَيْرُ بْنُ الأَخْنَسِ، قَالَ سَمِعْتُ أَنَسًا، يَقُولُ مُرَّ عَلَى النَّبِيِّ صلى الله عليه وسلم بِبَدَنَةٍ ‏.‏ فَذَكَرَ مِثْلَهُ ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَنْبَأَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ عَنْ قَتْلِ أَرْبَعٍ مِنَ الدَّوَابِّ النَّمْلَةِ وَالنَّحْلِ وَالْهُدْهُدِ وَالصُّرَدِ ‏.‏", chapter: "Chapters on Hunting", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ بَشَّارٍ، قَالَ حَدَّثَنَا وَكِيعٌ، قَالَ أَنْبَأَنَا مُوسَى بْنُ نَافِعٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، أَنَّهُ كَانَ يَكْرَهُ أَنْ يَأْخُذَ، الدَّنَانِيرَ مِنَ الدَّرَاهِمِ وَالدَّرَاهِمَ مِنَ الدَّنَانِيرِ ‏.‏", chapter: "The Book of Financial Transactions", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، وَيَعْقُوبُ بْنُ إِبْرَاهِيمَ، - وَاللَّفْظُ لَهُ - عَنْ عَبْدِ الرَّحْمَنِ، عَنْ مَالِكٍ، عَنْ دَاوُدَ بْنِ الْحُصَيْنِ، عَنْ أَبِي سُفْيَانَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم رَخَّصَ فِي الْعَرَايَا أَنْ تُبَاعَ بِخَرْصِهَا فِي خَمْسَةِ أَوْسُقٍ أَوْ مَا دُونَ خَمْسَةِ أَوْسُقٍ ‏.‏", chapter: "The Book of Financial Transactions", ref: "Nasai · Unknown" },
  { arabic: "وَعَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَدْرَكَهُ الْأَذَانُ فِي الْمَسْجِدِ ثُمَّ خَرَجَ لَمْ يَخْرُجْ لِحَاجَةٍ وَهُوَ لَا يُرِيدُ الرّجْعَة فَهُوَ مُنَافِق» . رَوَاهُ ابْن مَاجَه", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ، عَنْ نَافِعٍ،\n عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ لَتُقَاتِلُنَّ الْيَهُودَ فَلَتَقْتُلُنَّهُمْ حَتَّى يَقُولَ\n الْحَجَرُ يَا مُسْلِمُ هَذَا يَهُودِيٌّ فَتَعَالَ فَاقْتُلْهُ ‏\"‏ ‏.‏", chapter: "The Book of Tribulations and Portents of the Last Hour", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا أَبُو الْوَلِيدِ الطَّيَالِسِيُّ  ، حَدَّثَنَا شُعْبَةُ  ، عَنْ الْحَكَمِ بْنِ عُتَيْبَةَ  ، قَالَ : سَمِعْتُ أَبَا جُحَيْفَةَ   يَقُولُ : \" خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْبَطْحَاءِ بِالْهَاجِرَةِ،فَصَلَّى الظُّهْرَ رَكْعَتَيْنِ، وَالْعَصْرَ رَكْعَتَيْنِ، وَبَيْنَ يَدَيْهِ عَنَزَةٌ، وَإِنَّ الظُّعُنَ لَتَمُرُّ بَيْنَ يَدَيْهِ \"", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "السابع‏:‏ عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏ من غدا إلى المسجد أو راح، أعد الله له في الجنة نزلا كلما غدا أو راح‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏", chapter: "The Book of Miscellany", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَعَنْ أَنَسٍ ‏- رضى الله عنه ‏- قَالَ: قَالَ رَسُولُ اَللَّهِ ‏- صلى الله عليه وسلم ‏-{ طُوبَى لِمَنْ شَغَلَهُ عَيْبَهُ عَنْ عُيُوبِ اَلنَّاسِ }  أَخْرَجَهُ اَلْبَزَّارُ بِإِسْنَادٍ حَسَنٍ.‏  1‏ .‏‏1 ‏- ضعيف جدا وله شواهد، ولكنها كلها ضعيفة ‏-أيضا‏- كما قال الحافظ العراقي.‏", chapter: "The Comprehensive Book", ref: "Bulugh Almaram · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ، أَنَّهُ قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ عَامِرِ بْنِ رَبِيعَةَ، يَقُولُ إِنِّي لأُوتِرُ وَأَنَا أَسْمَعُ الإِقَامَةَ، أَوْ بَعْدَ الْفَجْرِ ‏.‏ يَشُكُّ عَبْدُ الرَّحْمَنِ أَىَّ ذَلِكَ قَالَ ‏.‏", chapter: "Tahajjud", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا نَصْرُ بْنُ الْمُهَاجِرِ، حَدَّثَنَا مُعَاوِيَةُ بْنُ عَمْرٍو، حَدَّثَنَا زَائِدَةُ، عَنْ مَنْصُورٍ، عَنْ مُجَاهِدٍ، عَنِ الْحَكَمِ، أَوِ ابْنِ الْحَكَمِ عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم بَالَ ثُمَّ تَوَضَّأَ وَنَضَحَ فَرْجَهُ ‏.‏", chapter: "Purification (Kitab Al-Taharah)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا هَاشِمُ بْنُ هَاشِمٍ، عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ مَنْ تَصَبَّحَ سَبْعَ تَمَرَاتِ عَجْوَةٍ لَمْ يَضُرُّهُ ذَلِكَ الْيَوْمَ سَمٌّ وَلاَ سِحْرٌ ‏\"‏ ‏.‏", chapter: "Medicine (Kitab Al-Tibb)", ref: "Abudawud · Unknown" },
  { arabic: "وَحَدَّثَنَا عَمْرٌو النَّاقِدُ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ، عَنْ \n أَبِي سَعِيدٍ، قَالَ نَهَى النَّبِيُّ صلى الله عليه وسلم عَنِ اخْتِنَاثِ الأَسْقِيَةِ ‏.‏", chapter: "The Book of Drinks", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا مَحْمُودُ بْنُ غَيْلاَنَ، قَالَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، قَالَ أَنْبَأَنَا مَعْمَرٌ، عَنْ أَيُّوبَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، رضى الله عنهما أَنَّ امْرَأَةً، مَخْزُومِيَّةً كَانَتْ تَسْتَعِيرُ الْمَتَاعَ فَتَجْحَدُهُ فَأَمَرَ النَّبِيُّ صلى الله عليه وسلم بِقَطْعِ يَدِهَا ‏.‏", chapter: "The Book of Cutting off the Hand of the Thief", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ يُوسُفَ الْفِرْيَابِيُّ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ عَطَاءٍ، حَدَّثَنَا طَلْحَةُ بْنُ زَيْدٍ، عَنْ رَاشِدٍ، قَالَ سَمِعْتُ وَابِصَةَ بْنَ مَعْبَدٍ، يَقُولُ رَأَيْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ يُصَلِّي فَكَانَ إِذَا رَكَعَ سَوَّى ظَهْرَهُ حَتَّى لَوْ صُبَّ عَلَيْهِ الْمَاءُ لاَسْتَقَرَّ ‏.‏", chapter: "Establishing the Prayer and the Sunnah Regarding Them", ref: "Ibnmajah · Unknown" },
  { arabic: "عَن سَلمَة بن الْأَكْوَع قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ إِنِّي رَجُلٌ أَصِيدُ أَفَأُصَلِّي فِي الْقَمِيصِ الْوَاحِدِ؟ قَالَ: نَعَمْ وَازْرُرْهُ وَلَوْ بِشَوْكَةٍ \". رَوَاهُ أَبُو دَاوُدَ وَرَوَى النَّسَائِيّ نَحوه", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، قَالَ‏:‏ أَخْبَرَنَا سُلَيْمَانُ بْنُ كَثِيرٍ، عَنْ حُصَيْنٍ، عَنِ الشَّعْبِيِّ، أَنَّهُ لَقِيَ فَارِسًا فَبَدَأَهُ بِالسَّلاَمِ، فَقُلْتُ‏:‏ تَبْدَأُهُ بِالسَّلاَمِ‏؟‏ قَالَ‏:‏ رَأَيْتُ شُرَيْحًا مَاشِيًا يَبْدَأُ بِالسَّلامِ‏.‏", chapter: "Greetings", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى، قَالَ‏:‏ حَدَّثَنَا وُهَيْبٌ، قَالَ‏:‏ حَدَّثَنَا سُهَيْلٌ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ‏:‏ أَهْلُ الْكِتَابِ لاَ تَبْدَأُوهُمْ بِالسَّلاَمِ، وَاضْطَرُّوهُمْ إِلَى أَضْيَقِ الطَّرِيقِ‏.‏", chapter: "The People of the Book", ref: "Aladab Almufrad · Unknown" },
  { arabic: "وَحَدَّثَنِي مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ حَمْزَةَ، وَسَالِمٍ، ابْنَىْ عَبْدِ اللَّهِ بْنِ عُمَرَ عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ الشُّؤْمُ فِي الدَّارِ وَالْمَرْأَةِ وَالْفَرَسِ ‏\"‏ ‏.‏", chapter: "General Subjects", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا زَكَرِيَّا بْنُ عَدِيٍّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، قَالَ قُتِلَ عُثْمَانُ رَضِيَ اللَّهُ عَنْهُ سَنَةَ خَمْسٍ وَثَلَاثِينَ فَكَانَتْ الْفِتْنَةُ خَمْسَ سِنِينَ مِنْهَا أَرْبَعَةُ أَشْهُرٍ لِلْحَسَنِ رَضِيَ اللَّهُ عَنْهُ‏.‏", chapter: "Musnad Uthman ibn Affan", ref: "Ahmed · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ، عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ لاَ يَحِلُّ لِرَجُلٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ، يَلْتَقِيَانِ فَيُعْرِضُ هَذَا وَيُعْرِضُ هَذَا، وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلاَمِ ‏\"‏‏.‏", chapter: "Good Manners and Form (Al-Adab)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا يَحْيَى بْنُ حَسَّانَ ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ ، عَنْ يَحْيَى بْنِ عَتِيقٍ ، قَالَ : قَرَأْتُ فِي بَعْضِ كُتُبِ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ  فِي الْقَوْمِ يَقَعُ عَلَيْهِمْ الْبَيْتُ، لَا يُدْرَى أَيُّهُمَا مَاتَ قَبْلُ؟ قَالَ :\" لَا يُوَرَّثُ الْأَمْوَاتُ بَعْضُهُمْ مِنْ بَعْضٍ، وَيُوَرَّثُ الْأَحْيَاءُ مِنْ الْأَمْوَاتِ \"", chapter: "مِنْ كِتَابِ الْفَرَائِضِ", ref: "Darimi · Unknown" },
  { arabic: "وَحَدَّثَنَاهُ سَعِيدُ بْنُ مَنْصُورٍ، حَدَّثَنَا سُفْيَانُ، عَنْ قَعْنَبٍ، عَنْ عَلْقَمَةَ بْنِ مَرْثَدٍ، بِهَذَا\n الإِسْنَادِ ‏\"‏ فَقَالَ فَخُذْ مِنْ حَسَنَاتِهِ مَا شِئْتَ ‏\"‏ ‏.‏ فَالْتَفَتَ إِلَيْنَا رَسُولُ اللَّهِ صلى الله عليه\n وسلم فَقَالَ ‏\"‏ فَمَا ظَنُّكُمْ ‏\"‏ ‏.‏", chapter: "The Book on Government", ref: "Muslim · Unknown" },
  { arabic: "وَعَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «خِيَارُكُمْ أَلْيَنُكُمْ مَنَاكِبَ فِي الصَّلَاة» . رَوَاهُ أَبُو دَاوُد", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي حُسَيْنٍ الْمَكِّيِّ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ لاَ قَطْعَ فِي ثَمَرٍ مُعَلَّقٍ وَلاَ فِي حَرِيسَةِ جَبَلٍ ‏\"‏ فَإِذَا آوَاهُ الْمُرَاحُ أَوِ الْجَرِينُ فَالْقَطْعُ فِيمَا يَبْلُغُ ثَمَنَ الْمِجَنِّ ‏.‏", chapter: "Hudud", ref: "Malik · Unknown" },
  { arabic: "أَخْبَرَنَا يَزِيدُ بْنُ هَارُونَ  ، عَنْ عَبْدِ الْمَلِكِ بْنِ أَبِي سُلَيْمَانَ  ، عَنْ أَبِي الزُّبَيْرِ  ،  عَنْ جَابِرٍ  ، قَالَ : \" كَانَيُنْتَبَذُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السِّقَاءِ، فَإِنْ لَمْ يَكُنْ سِقَاءٌ، نُبِذَ لَهُ فِي تَوْرٍ مِنْ بِرَامٍ \"", chapter: "وَمِنْ كِتَابِ الْأَشْرِبَةِ", ref: "Darimi · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ عِيسَى ، حَدَّثَنَا هُشَيْمٌ ، حَدَّثَنَا يُونُسُ ، عَنْ الْحَسَنِ  فِي الْحَائِضِ\" تُصَلِّي الصَّلَاةَ الَّتِي طَهُرَتْ فِي وَقْتِهَا \"", chapter: "كِتَاب الطَّهَارَةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، قَالَ‏:‏ حَدَّثَنَا ضَمْضَمُ بْنُ عَمْرٍو الْحَنَفِيُّ، قَالَ‏:‏ حَدَّثَنَا كُلَيْبُ بْنُ مَنْفَعَةَ قَالَ‏:‏ قَالَ جَدِّي‏:‏ يَا رَسُولَ اللهِ، مَنْ أَبَرُّ‏؟‏ قَالَ‏:‏ أُمَّكَ وَأَبَاكَ، وَأُخْتَكَ وَأَخَاكَ، وَمَوْلاَكَ الَّذِي يَلِي ذَاكَ، حَقٌّ وَاجِبٌ، وَرَحِمٌ مَوْصُولَةٌ‏.‏", chapter: "Ties of Kinship", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ أَبِي سُلَيْمَانَ، عَنْ عَطَاءٍ، عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ ‏.‏", chapter: "The Book on Virtues of Jihad", ref: "Tirmidhi · Unknown" },
  { arabic: "عَن سَمُرَة بن جُنْدُب قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كُسُوفٍ لَا نَسْمَعُ لَهُ صَوْتًا. رَوَاهُ التِّرْمِذِيُّ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا أَبُو شِهَابٍ، عَنْ مُغِيرَةَ بْنِ زِيَادٍ، عَنْ عَدِيِّ بْنِ عَدِيٍّ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ قَالَ ‏\n\"‏ مَنْ شَهِدَهَا فَكَرِهَهَا كَانَ كَمَنْ غَابَ عَنْهَا ‏\"‏ ‏.‏", chapter: "Battles (Kitab Al-Malahim)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، حَدَّثَنَا شُعْبَةُ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ لَمَّا نَزَلَتْ آخِرُ الْبَقَرَةِ قَرَأَهُنَّ النَّبِيُّ صلى الله عليه وسلم عَلَيْهِمْ فِي الْمَسْجِدِ، ثُمَّ حَرَّمَ التِّجَارَةَ فِي الْخَمْرِ‏.‏", chapter: "Sales and Trade", ref: "Buhari · Unknown" },
  { arabic: "وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ جَمِيعًا عَنْ وَكِيعٍ، ح وَحَدَّثَنِيهِ أَبُو الطَّاهِرِ، أَخْبَرَنَا ابْنُ وَهْبٍ، كِلاَهُمَا عَنْ مُوسَى بْنِ عُلَىٍّ، بِهَذَا الإِسْنَادِ .‏", chapter: "The Book of Fasting", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا جَرِيرٌ، وَعِيسَى بْنُ يُونُسَ، ح وَحَدَّثَنَاهُ عَلِيُّ بْنُ خَشْرَمٍ، أَخْبَرَنَا عِيسَى، جَمِيعًا عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "وعن أبي بكر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال في خطبته يوم النحر بمنًى في حجة الوداع‏:‏ ‏\"‏إن دماءكم، وأموالكم، وأعراضكم حرام عليكم كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا، ألا هل بلغت” ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَمْرِو بْنِ الْوَلِيدِ الْكِنْدِيُّ الْكُوفِيُّ، قَالَ‏:‏ حَدَّثَنَا يَحْيَى بْنُ آدَمَ، عَنْ شَرِيكٍ، عَنْ عُبَيْدِ اللهِ بْنِ عُمَرَ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللهِ بْنِ عُمَرَ، قَالَ‏:‏ إِنَّمَا كَانَ شَيْبُ رَسُولِ اللهِ صلى الله عليه وسلم نَحْوًا مِنْ عِشْرِينَ شَعَرَةً بَيْضَاءَ‏.‏", chapter: "Appearing Of The White Hair Of Rasoolullah", ref: "Shamail Muhammadiyah · Unknown" },
  { arabic: "وعن أبي موسى الأشعري قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏المملوك الذي يحسن عبادة ربه ويؤدي إلى سيده الذي عليه من الحق، والنصيحة والطاعة له أجران‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏", chapter: "The Book of Jihad", ref: "Riyad Assalihin · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ خَالِدِ بْنِ يَزِيدَ، عَنْ سَعِيدِ بْنِ أَبِي هِلاَلٍ، عَنْ يَزِيدَ بْنِ عَبْدِ اللَّهِ، عَنْ عُمَيْرٍ، مَوْلَى آبِي اللَّحْمِ عَنْ آبِي اللَّحْمِ، أَنَّهُ رَأَى رَسُولَ اللَّهِ صلى الله عليه وسلم عِنْدَ أَحْجَارِ الزَّيْتِ يَسْتَسْقِي وَهُوَ مُقْنِعٌ بِكَفَّيْهِ يَدْعُو ‏.‏", chapter: "The Book of Praying for Rain (Al-Istisqa')", ref: "Nasai · Unknown" },
  { arabic: "وَعَنْ أَبِي هُرَيْرَةَ قَالَ: قِيلَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيْ النِّسَاءِ خَيْرٌ؟ قَالَ: «الَّتِي تَسُرُّهُ إِذَا نَظَرَ وَتُطِيعُهُ إِذَا أَمَرَ وَلَا تُخَالِفُهُ فِي نَفْسِهَا وَلَا مَالِهَا بِمَا يَكْرَهُ» . رَوَاهُ النَّسَائِيُّ وَالْبَيْهَقِيُّ فِي شُعَبِ الْإِيمَان", chapter: "Marriage", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَحَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنِي إِبْرَاهِيمُ،\n عَنِ الأَسْوَدِ، عَنْ عَبْدِ اللَّهِ، قَالَ بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي غَارٍ\n ‏.‏ بِمِثْلِ حَدِيثِ جَرِيرٍ وَأَبِي مُعَاوِيَةَ ‏.‏", chapter: "The Book of Greetings", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا ابْنُ رَافِعٍ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، أَخْبَرَنَا الضَّحَّاكُ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِ حَدِيثِ عَبْدِ الْوَهَّابِ ‏.‏", chapter: "The Book of Transactions", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا عَمْرُو بْنُ مَنْصُورٍ، قَالَ حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ، عَنْ خَالِدٍ، عَنْ حَفْصَةَ، عَنْ أُمِّ عَطِيَّةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ فِي غُسْلِ ابْنَتِهِ ‏\n\"‏ ابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ مِنْهَا ‏\"‏ ‏.‏", chapter: "The Book of Funerals", ref: "Nasai · Unknown" },
  { arabic: "عن أبي الشعثاء قال‏:‏ كنا قعودًا مع أبي هريرة رضي الله عنه في المسجد فأذن المؤذن، فقام رجل من المسجد يمشي، فأتبعه أبو هريرة بصره حتى خرج من المسجد فقال أبو هريرة‏:‏ أما هذا فقد عصى أبا القاسم صلى الله عليه وسلم ‏\"‏ ‏(‏‏(‏‏رواه مسلم‏)‏‏)‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَعَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اَللَّهِ ‏- صلى الله عليه وسلم ‏-{ مَنْ خَافَ أَنْ لَا يَقُومَ مِنْ آخِرِ اَللَّيْلِ فَلْيُوتِرْ أَوَّلَهُ, وَمَنْ طَمِعَ أَنْ يَقُومَ آخِرَهُ فَلْيُوتِرْ آخِرَ اَللَّيْلِ, فَإِنَّ صَلَاةَ آخِرِ اَللَّيْلِ مَشْهُودَةٌ, وَذَلِكَ أَفْضَلُ }  رَوَاهُ مُسْلِمٌ .‏  1‏ .‏‏1 ‏- صحيح.‏ رواه مسلم (755)‏.‏", chapter: "The Book of Prayer", ref: "Bulugh Almaram · Unknown" },
  { arabic: "حَدَّثَنَا زَكَرِيَّا، قَالَ‏:‏ حَدَّثَنَا الْحَكَمُ بْنُ الْمُبَارَكِ، قَالَ‏:‏ حَدَّثَنَا زِيَادُ بْنُ الرَّبِيعِ قَالَ‏:‏ حَدَّثَنِي عَبَّادٌ الرَّمْلِيُّ قَالَ‏:‏ حَدَّثَتْنِي امْرَأَةٌ يُقَالُ لَهَا‏:‏ فُسَيْلَةُ، قَالَتْ‏:‏ سَمِعْتُ أَبِي يَقُولُ‏:‏ قُلْتُ‏:‏ يَا رَسُولَ اللهِ، أَمِنَ الْعَصَبِيَّةِ أَنْ يُعِينَ الرَّجُلُ قَوْمَهُ عَلَى ظُلْمٍ‏؟‏ قَالَ‏:‏ نَعَمْ‏.‏", chapter: "Social Behaviour", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَابْنُ الْمُثَنَّى، عَنْ مُحَمَّدِ بْنِ جَعْفَرٍ، عَنْ شُعْبَةَ، عَنْ مَنْصُورٍ، ح وَحَدَّثَنَا ابْنُ نُمَيْرٍ، حَدَّثَنَا عَفَّانُ، حَدَّثَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، كِلاَهُمَا عَنْ أَبِي وَائِلٍ، عَنْ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِهِ ‏.‏", chapter: "The Book of Faith", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ الرَّحِيمِ بْنُ سُلَيْمَانَ، عَنْ هِشَامٍ، عَنْ حَفْصَةَ، بِنْتِ سِيرِينَ عَنْ أُمِّ عَطِيَّةَ الأَنْصَارِيَّةِ، قَالَتْ غَزَوْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم سَبْعَ غَزَوَاتٍ أَخْلُفُهُمْ فِي رِحَالِهِمْ فَأَصْنَعُ لَهُمُ الطَّعَامَ وَأُدَاوِي الْجَرْحَى وَأَقُومُ عَلَى الْمَرْضَى.", chapter: "The Book of Jihad and Expeditions", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، قَالَ حَدَّثَنَا أَبُو دَاوُدَ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، قَالَ سَمِعْتُ مُطَرِّفَ بْنَ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ، يُحَدِّثُ عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ فِي صَوْمِ الدَّهْرِ ‏\n\"‏ لاَ صَامَ وَلاَ أَفْطَرَ ‏\"‏ ‏.‏", chapter: "The Book of Fasting", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا شَيْبَانُ بْنُ فَرُّوخَ، أَخْبَرَنَا أَبُو عَوَانَةَ، عَنْ سُهَيْلٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ،\n قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ صِيَاحُ الْمَوْلُودِ حِينَ يَقَعُ نَزْغَةٌ مِنَ الشَّيْطَانِ\n ‏\"‏ ‏.‏", chapter: "The Book of Virtues", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، قَالَ‏:‏ حَدَّثَنَا هِشَامٌ، قَالَ‏:‏ حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، أَنَّ رَجُلاً سَأَلَ النَّبِيَّ صلى الله عليه وسلم فَقَالَ‏:‏ يَا نَبِيَّ اللهِ، مَتَى السَّاعَةُ‏؟‏ فَقَالَ‏:‏ وَمَا أَعْدَدْتَ لَهَا‏؟‏ قَالَ‏:‏ مَا أَعْدَدْتُ مِنْ كَبِيرٍ، إِلاَّ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ، فَقَالَ‏:‏ الْمَرْءُ مَعَ مَنْ أَحَبَّ‏.‏", chapter: "Visitation", ref: "Aladab Almufrad · Unknown" },
  { arabic: "أَخْبَرَنَا الْحَكَمُ بْنُ الْمُبَارَكِ ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ، عَنْ مُفَضَّلِ بْنِ مُهَلْهَلٍ ، عَنْ سُفْيَانَ ، عَنْ ابْنِ جُرَيْجٍ ، عَنْ عَطَاءٍ ، قَالَ :\" أَقْصَى الْحَيْضِ خَمْسَ عَشْرَةَ \"", chapter: "كِتَاب الطَّهَارَةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنه ـ ‏{‏وَمَا جَعَلْنَا الرُّؤْيَا الَّتِي أَرَيْنَاكَ إِلاَّ فِتْنَةً لِلنَّاسِ‏}‏ قَالَ هِيَ رُؤْيَا عَيْنٍ أُرِيَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم لَيْلَةَ أُسْرِيَ بِهِ ‏{‏وَالشَّجَرَةَ الْمَلْعُونَةَ‏}‏ شَجَرَةُ الزَّقُّومِ‏.‏", chapter: "Prophetic Commentary on the Qur'an (Tafseer of the Prophet (pbuh))", ref: "Buhari · Unknown" },
  { arabic: "وَعَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا يَدْخُلُ الْجَنَّةَ صَاحِبُ مَكْسٍ» : يَعْنِي الَّذِي يَعْشُرُ النَّاسَ. رَوَاهُ أَحْمد وَأَبُو دَاوُد والدارمي", chapter: "The Offices of Commander and Qadi", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ عَطَاءٍ، عَنْ جَابِرٍ، قَالَ كُنَّا نَعْزِلُ عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم‏.‏", chapter: "Wedlock, Marriage (Nikaah)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبَّادُ بْنُ الْعَوَّامِ، عَنِ الشَّيْبَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ شَدَّادٍ، قَالَ حَدَّثَتْنِي مَيْمُونَةُ، زَوْجُ النَّبِيِّ ـ صلى الله عليه وسلم ـ قَالَتْ كَانَ النَّبِيُّ ـ صلى الله عليه وسلم ـ يُصَلِّي وَأَنَا بِحِذَائِهِ وَرُبَّمَا أَصَابَنِي ثَوْبُهُ إِذَا سَجَدَ ‏.‏", chapter: "Establishing the Prayer and the Sunnah Regarding Them", ref: "Ibnmajah · Unknown" },
  { arabic: "عن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏إذا دعا الرجل امرأته إلى فراشه فأبت، فبات غضبان عليها، لعنتها الملائكة حتى تصبح‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ ‏\nوفي رواية‏:‏ حتى‏:‏ ‏ ‏ترجع‏‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "أَخْبَرَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ حَدَّثَنَا هُشَيْمٌ، عَنْ يَحْيَى بْنِ سَعِيدٍ، قَالَ حَدَّثَنَا نَافِعٌ، عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ الْمُتَبَايِعَانِ لاَ بَيْعَ بَيْنَهُمَا حَتَّى يَتَفَرَّقَا إِلاَّ بَيْعَ الْخِيَارِ ‏\"‏ ‏.‏", chapter: "The Book of Financial Transactions", ref: "Nasai · Unknown" },
  { arabic: "وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَمِعَ الْمُؤَذِّنَ يَتَشَهَّدُ قَالَ: «وَأَنَا وَأَنَا» . رَوَاهُ أَبُو دَاوُد", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو النُّعْمَانِ، حَدَّثَنَا حَمَّادٌ، عَنْ أَبِي عِمْرَانَ الْجَوْنِيِّ، عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ اقْرَءُوا الْقُرْآنَ مَا ائْتَلَفَتْ قُلُوبُكُمْ، فَإِذَا اخْتَلَفْتُمْ فَقُومُوا عَنْهُ ‏\"‏‏.‏", chapter: "Virtues of the Qur'an", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنِي مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، حَدَّثَنَا شُعْبَةُ، عَنِ الْمُغِيرَةِ بْنِ النُّعْمَانِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ اخْتَلَفَ أَهْلُ الْكُوفَةِ فِي قَتْلِ الْمُؤْمِنِ، فَرَحَلْتُ فِيهِ إِلَى ابْنِ عَبَّاسٍ، فَقَالَ نَزَلَتْ فِي آخِرِ مَا نَزَلَ وَلَمْ يَنْسَخْهَا شَىْءٌ‏.‏", chapter: "Prophetic Commentary on the Qur'an (Tafseer of the Prophet (pbuh))", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا يَحْيَى بْنُ بِسْطَامَ  ، عَنْ يَحْيَى بْنِ حَمْزَةَ  ، حَدَّثَنِي يَحْيَى بْنُ الْحَارِثِ  ، عَنْ الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ  ، عَنْ تَمِيمٍ الدَّارِيِّ  .\nح وَحَدَّثَنِي عُثْمَانُ بْنُ مُسْلِمٍ  ، عَنْ الْعَبَّاسِ بْنِ مَيْمُونٍ  ، عَنْ تَمِيمٍ الدَّارِيِّ  ، قَالَ :\" مَنْ قَرَأَ عَشْرَ آيَاتٍ فِي لَيْلَةٍ، لَمْ يُكْتَبْ مِنْ الْغَافِلِينَ \"", chapter: "وَمِنْ كِتَابِ فَضَائِلِ الْقُرْآنِ", ref: "Darimi · Unknown" },
  { arabic: "وَعَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي السَّفَرِ عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ يُومِئُ إِيمَاءً صَلَاةَ اللَّيْلِ إِلَّا الْفَرَائِضَ وَيُوتِرُ على رَاحِلَته", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ، حَدَّثَنَا حَفْصٌ ، عَنْ إِسْمَاعِيل بْنِ أَبِي خَالِدٍ ، عَنِ الْحَكَمِ ، عَنْ إِبْرَاهِيمَ ، قَالَ :\" الْكَفَنُ مِنْ جَمِيعِ الْمَالِ \"", chapter: "مِنْ كِتَابِ الْوَصَايَا", ref: "Darimi · Unknown" },
  { arabic: "وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: \n\" مَا مِنْ مَيِّتٍ تُصَلِّي عَلَيْهِ أُمَّةٌ مِنَ الْمُسْلِمِينَ يَبْلُغُونَ مِائَةً كُلُّهُمْ يَشْفَعُونَ لَهُ: إِلَّا شفعوا فِيهِ \". رَوَاهُ مُسلم", chapter: "Funerals", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكٌ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي بِاللَّيْلِ ثَلاَثَ عَشْرَةَ رَكْعَةً، ثُمَّ يُصَلِّي إِذَا سَمِعَ النِّدَاءَ بِالصُّبْحِ رَكْعَتَيْنِ خَفِيفَتَيْنِ‏.‏", chapter: "Prayer at Night (Tahajjud)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو الرَّبِيعِ، حَدَّثَنَا ابْنُ عُيَيْنَةَ، عَنِ ابْنِ جُرَيْجٍ، عَنْ عَطَاءٍ، عَنْ جَابِرٍ ـ رضى الله عنه ـ قَالَ النَّبِيُّ صلى الله عليه وسلم حِينَ مَاتَ النَّجَاشِيُّ ‏\n\"‏ مَاتَ الْيَوْمَ رَجُلٌ صَالِحٌ، فَقُومُوا فَصَلُّوا عَلَى أَخِيكُمْ أَصْحَمَةَ ‏\"‏‏.‏", chapter: "Merits of the Helpers in Madinah (Ansaar)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا الْقَعْنَبِيُّ، عَنْ مَالِكٍ، عَنْ حُمَيْدٍ الطَّوِيلِ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ قَالَ حَجَمَ أَبُو طَيْبَةَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَمَرَ لَهُ بِصَاعٍ مِنْ تَمْرٍ وَأَمَرَ أَهْلَهُ أَنْ يُخَفِّفُوا عَنْهُ مِنْ خَرَاجِهِ ‏.‏", chapter: "Wages (Kitab Al-Ijarah)", ref: "Abudawud · Unknown" },
  { arabic: "أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، قَالَ حَدَّثَنِي أَبُو كَثِيرٍ، أَنَّهُ سَمِعَ أَبَا هُرَيْرَةَ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ إِذَا بَاعَ أَحَدُكُمُ الشَّاةَ أَوِ اللَّقْحَةَ فَلاَ يُحَفِّلْهَا ‏\"‏ ‏.‏", chapter: "The Book of Financial Transactions", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ الْمُصَفَّى، حَدَّثَنَا بَقِيَّةُ، حَدَّثَنِي ثَوْرُ بْنُ يَزِيدَ، عَنْ صَالِحِ بْنِ يَحْيَى بْنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنْ خَالِدِ بْنِ الْوَلِيدِ، قَالَ نَهَى رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ عَنْ لُحُومِ الْخَيْلِ وَالْبِغَالِ وَالْحَمِيرِ ‏.‏", chapter: "Chapters on Slaughtering", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ  ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ  ، عَنْ أَيُّوبَ  ، عَنْ أَبِي قِلَابَةَ  ، أَنَّ رَجُلًا أَتَى أَبَا بَكْرٍ   رَضِيَ اللهُ عَنْهُ، فَقَالَ : رَأَيْتُ فِي الْمَنَامِ كَأَنِّي أَبُولُ دَمًا، قَالَ : تَأْتِي امْرَأَتَكَ وَهِيَ حَائِضٌ؟، قَالَ : نَعَمْ، قَالَ :\" اتَّقِ اللَّهَ، وَلَا تَعُدْ \"", chapter: "كِتَاب الطَّهَارَةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا سَعِيدُ بْنُ أَزْهَرَ الْوَاسِطِيُّ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، حَدَّثَنَا أَبُو مَالِكٍ الأَشْجَعِيُّ،\n عَنْ أَبِيهِ، قَالَ كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبِيُّ صلى الله عليه وسلم الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ\n يَدْعُوَ بِهَؤُلاَءِ الْكَلِمَاتِ ‏\n\"‏ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَعَافِنِي وَارْزُقْنِي ‏\"‏ ‏.‏", chapter: "The Book Pertaining to the Remembrance of Allah, Supplication, Repentance and Seeking Forgiveness", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا عَمْرُو بْنُ رَافِعٍ الْبَجَلِيُّ، حَدَّثَنَا الْفَضْلُ بْنُ مُوسَى، عَنِ الْحُسَيْنِ بْنِ وَاقِدٍ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ مَنْ قَالَ إِنِّي بَرِيءٌ مِنَ الإِسْلاَمِ فَإِنْ كَانَ كَاذِبًا فَهُوَ كَمَا قَالَ وَإِنْ كَانَ صَادِقًا لَمْ يَعُدْ إِلَيْهِ الإِسْلاَمُ سَالِمًا ‏\"‏ ‏.‏", chapter: "The Chapters on Expiation", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا إِسْمَاعِيلُ بْنُ مَسْعُودٍ، قَالَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، قَالَ حَدَّثَنَا سَعِيدٌ، قَالَ حَدَّثَنَا قَتَادَةُ، أَنَّ مُوسَى بْنَ سَلَمَةَ، حَدَّثَهُمْ أَنَّهُ، سَأَلَ ابْنَ عَبَّاسٍ قُلْتُ تَفُوتُنِي الصَّلاَةُ فِي جَمَاعَةٍ وَأَنَا بِالْبَطْحَاءِ، مَا تَرَى أَنْ أُصَلِّيَ، قَالَ رَكْعَتَيْنِ سُنَّةَ أَبِي الْقَاسِمِ صلى الله عليه وسلم ‏.‏", chapter: "The Book of Shortening the Prayer When Traveling", ref: "Nasai · Unknown" },
  { arabic: "وَحَدَّثَنِيهِ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الدَّارِمِيُّ، أَخْبَرَنَا يَحْيَى بْنُ حَسَّانَ، حَدَّثَنَا مُعَاوِيَةُ بْنُ سَلاَّمٍ، فِي هَذَا الإِسْنَادِ بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ كُنْتُ قَاعِدًا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَقَالَ زَائِدَةُ كَبِدِ النُّونِ ‏.‏ وَقَالَ أَذْكَرَ وَآنَثَ ‏.‏ وَلَمْ يَقُلْ أَذْكَرَا وَآنَثَا ‏.‏", chapter: "The Book of Menstruation", ref: "Muslim · Unknown" },
  { arabic: "وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ تَعْنِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنَامُ أَوَّلَ اللَّيْلِ وَيُحْيِي آخِرَهُ ثُمَّ إِنْ كَانَتْ لَهُ حَاجَةٌ إِلَى أَهْلِهِ قَضَى حَاجَتَهُ ثُمَّ يَنَامُ فَإِنْ كَانَ عِنْدَ النداء الأول جنبا وثب فَأَفَاضَ عَلَيْهِ الماس وَإِنْ لَمْ يَكُنْ جُنُبًا تَوَضَّأَ لِلصَّلَاةِ ثُمَّ صلى رَكْعَتَيْنِ \"", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، بِإِسْنَادِهِ بِهَذَا قَالَتْ حَتَّى إِذَا كَانَ عِنْدَ بَابِ الْمَسْجِدِ الَّذِي عِنْدَ بَابِ أُمِّ سَلَمَةَ مَرَّ بِهِمَا رَجُلاَنِ ‏.‏ وَسَاقَ مَعْنَاهُ ‏.‏", chapter: "Fasting (Kitab Al-Siyam)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا قَبِيصَةُ، حَدَّثَنَا سُفْيَانُ، عَنْ طَارِقٍ، قَالَ ذُكِرَتْ عِنْدَ سَعِيدِ بْنِ الْمُسَيَّبِ الشَّجَرَةُ فَضَحِكَ فَقَالَ أَخْبَرَنِي أَبِي وَكَانَ، شَهِدَهَا‏.‏", chapter: "Military Expeditions led by the Prophet (pbuh) (Al-Maghaazi)", ref: "Buhari · Unknown" },
  { arabic: "وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏ اثنتان في الناس هما بهم كفر‏:‏ الطعن في النسب، والنياحة على الميت‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا شُعْبَةُ، عَنْ عَلِيِّ بْنِ مُدْرِكٍ، سَمِعْتُ أَبَا زُرْعَةَ بْنَ عَمْرِو بْنِ جَرِيرٍ، عَنْ جَدِّهِ، جَرِيرٍ قَالَ قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم فِي حَجَّةِ الْوَدَاعِ ‏\"‏ اسْتَنْصِتِ النَّاسَ ‏\"‏‏.‏ ثُمَّ قَالَ ‏\"‏ لاَ تَرْجِعُوا بَعْدِي كُفَّارًا، يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏\"‏‏.‏", chapter: "Afflictions and the End of the World", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا وَكِيعٌ، وَعُثْمَانُ بْنُ عُمَرَ، قَالَا حَدَّثَنَا أُسَامَةُ بْنُ زَيْدٍ، قَالَ وَكِيعٌ قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ حُنَيْنٍ، وَقَالَ، عُثْمَانُ عَنْ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ، سَمِعْتُ عَلِيًّا، رَضِيَ اللَّهُ عَنْهُ يَقُولُ نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا أَقُولُ نَهَاكُمْ عَنْ الْمُعَصْفَرِ وَالتَّخَتُّمِ بِالذَّهَبِ‏.‏", chapter: "Musnad 'Ali Ibn Abi Talib", ref: "Ahmed · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو نُعَيْمٍ، قَالَ‏:‏ حَدَّثَنَا سُفْيَانُ، عَنْ مُغِيرَةَ، عَنْ إِبْرَاهِيمَ، أَنَّ عَبْدَ اللهِ كَنَّى عَلْقَمَةَ‏:‏ أَبَا شِبْلٍ، وَلَمْ يُولَدْ لَهُ‏.‏", chapter: "Kunyas", ref: "Aladab Almufrad · Unknown" },
  { arabic: "أَخْبَرَنَا عَمْرُو بْنُ عَلِيٍّ، قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ فُضَيْلٍ، قَالَ حَدَّثَنَا أَبُو يَعْفُورٍ، قَالَ حَدَّثَنَا إِبْرَاهِيمُ، عَنْ صِلَةَ بْنِ زُفَرَ، قَالَ تَسَحَّرْتُ مَعَ حُذَيْفَةَ ثُمَّ خَرَجْنَا إِلَى الْمَسْجِدِ فَصَلَّيْنَا رَكْعَتَىِ الْفَجْرِ ثُمَّ أُقِيمَتِ الصَّلاَةُ فَصَلَّيْنَا ‏.‏", chapter: "The Book of Fasting", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنِي مُحَمَّدُ بْنُ يَحْيَى بْنِ أَيُّوبَ، قَالَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، قَالَ حَدَّثَنَا ابْنُ أَبِي ذِئْبٍ، عَنِ الزُّهْرِيِّ، عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، عَنْ أَبِيهِ، قَالَ الصَّائِمُ فِي السَّفَرِ كَالْمُفْطِرِ فِي الْحَضَرِ ‏.‏", chapter: "The Book of Fasting", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرٍ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَنَا فِي، أَرْضٍ بَارِدَةٍ فَكَيْفَ الْغُسْلُ مِنَ الْجَنَابَةِ فَقَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ أَمَّا أَنَا فَأَحْثُو عَلَى رَأْسِي ثَلاَثًا ‏\"‏ ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ، وَالْحَارِثُ بْنُ مِسْكِينٍ، قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ، وَاللَّفْظُ، لَهُ عَنِ ابْنِ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمٍ، عَنْ أَبِيهِ، قَالَ رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُهِلُّ مُلَبِّدًا ‏.‏", chapter: "The Book of Hajj", ref: "Nasai · Unknown" },
  { arabic: "وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم  كان يخرج من طريق الشجرة، ويدخل من طريق المعرس، وإذا دخل مكة دخل من الثنية العليا ويخرج من الثنية السفلى‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏", chapter: "The Book of Good Manners", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَعَن أبي هُرَيْرَة قَالَ: كَانَ قِرَاءَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ يَرْفَعُ طَوْرًا وَيَخْفِضُ طَوْرًا. رَوَاهُ أَبُو دَاوُدَ", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صلى الله عليه و سلم قَالَ: \"لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعَى رِجَالٌ أَمْوَالَ قَوْمٍ وَدِمَاءَهُمْ، لَكِنَّ الْبَيِّنَةَ عَلَى الْمُدَّعِي، وَالْيَمِينَ عَلَى مَنْ أَنْكَرَ\" . \nحَدِيثٌ حَسَنٌ، رَوَاهُ الْبَيْهَقِيّ ، وَغَيْرُهُ هَكَذَا، وَبَعْضُهُ فِي \"الصَّحِيحَيْنِ\".", chapter: "Forty Hadith of an-Nawawi", ref: "Nawawi40 · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، حَدَّثَنَا يَحْيَى، عَنِ ابْنِ الْمُنْكَدِرِ، أَنَّ هَزَّالاً، أَمَرَ مَاعِزًا أَنْ يَأْتِيَ النَّبِيَّ صلى الله عليه وسلم فَيُخْبِرَهُ ‏.‏", chapter: "Prescribed Punishments (Kitab Al-Hudud)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا أَبِي وَيَعْلَى، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، عَنْ نُفَيْعٍ، عَنْ أَنَسٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ مَا مِنْ غَنِيٍّ وَلاَ فَقِيرٍ إِلاَّ وَدَّ يَوْمَ الْقِيَامَةِ أَنَّهُ أُتِيَ مِنَ الدُّنْيَا قُوتًا ‏\"‏ ‏.‏", chapter: "Zuhd", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عَقِيلٍ، حَدَّثَنَا عَمْرُو بْنُ عَاصِمٍ، حَدَّثَنَا أَبُو الْعَوَّامِ الْقَطَّانُ، عَنْ مُحَمَّدِ بْنِ جُحَادَةَ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، عَنْ أُسَامَةَ بْنِ شَرِيكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ لاَ تَجْنِي نَفْسٌ عَلَى أُخْرَى ‏\"‏ ‏.‏", chapter: "The Chapters on Blood Money", ref: "Ibnmajah · Unknown" },
  { arabic: "وَحَدَّثَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي قَتَادَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم\n بِمِثْلِ هَذَا الْحَدِيثِ ‏.‏", chapter: "The Book of Drinks", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا يَعْقُوبُ بْنُ حُمَيْدِ بْنِ كَاسِبٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ، ح وَحَدَّثَنَا أَبُو إِسْحَاقَ الْهَرَوِيُّ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، جَمِيعًا عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ ‏\n\"‏ جُعِلَتْ لِيَ الأَرْضُ مَسْجِدًا وَطَهُورًا ‏\"‏ ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا يَحْيَى بْنُ حَسَّانَ  ، حَدَّثَنَا يَحْيَى هُوَ ابْنُ حَمْزَةَ  ، عَنْ زَيْدِ بْنِ وَاقِدٍ  ، عَنْ مَكْحُولٍ  ، قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :\" لَا يَرِثُ الْمَوْلُودُ حَتَّى يَسْتَهِلَّ صَارِخًا، وَإِنْ وَقَعَ حَيًّا \"", chapter: "مِنْ كِتَابِ الْفَرَائِضِ", ref: "Darimi · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ عِيسَى ، حَدَّثَنَا عَبْدُ الْوَارِثِ ، عَنْ عَمْرٍو ، عَنْ الْحَسَنِ ، قَالَ :\" إِذَا صَلَّتْ الْمَرْأَةُ رَكْعَتَيْنِ، ثُمَّ حَاضَتْ فَلَا تَقْضِي إِذَا طَهُرَتْ \"", chapter: "كِتَاب الطَّهَارَةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ الْجَرَّاحِ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ عَبْدِ الْكَرِيمِ، عَنْ مِقْسَمٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ الرَّجُلُ إِذَا وَقَعَ عَلَى امْرَأَتِهِ وَهِيَ حَائِضٌ أَمَرَهُ النَّبِيُّ ـ صلى الله عليه وسلم ـ أَنْ يَتَصَدَّقَ بِنِصْفِ دِينَارٍ ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "وعن عثمان بن عفان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏من توضأ فأحسن الوضوء، خرجت خطاياه من جسده حتى تخرج من تحت أظفاره‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏", chapter: "The Book of Virtues", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنِ ابْنِ ذَكْوَانَ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ مَطْلُ الْغَنِيِّ ظُلْمٌ، وَمَنْ أُتْبِعَ عَلَى مَلِيٍّ فَلْيَتَّبِعْ ‏\"‏‏.‏", chapter: "Transferance of a Debt from One Person to Another (Al-Hawaala)", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا أَبُو نُعَيْمٍ ، حَدَّثَنَا زُهَيْرٌ ، عَنْ الْحَسَنِ بْنِ الْحُرِّ ، حَدَّثَنِي الْحَكَمُ  : أَنَّ\" وَلَدَ الزِّنَا لَا يَرِثُهُ الَّذِي يَدَّعِيهِ، وَلَا يَرِثُهُ الْمَوْلُودُ \"", chapter: "مِنْ كِتَابِ الْفَرَائِضِ", ref: "Darimi · Unknown" },
  { arabic: "وَعَن سَخْبَرَة الْأَزْدِيّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مِنْ طَلَبَ الْعِلْمَ كَانَ كَفَّارَةً لِمَا مَضَى» . رَوَاهُ التِّرْمِذِيُّ وَالدَّارِمِيُّ وَقَالَ التِّرْمِذِيُّ: هَذَا حَدِيثٌ ضَعِيفُ الْإِسْنَادِ وَأَبُو دَاوُدَ الرَّاوِي يُضَعَّفُ", chapter: "Knowledge", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا عُثْمَانُ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، مِثْلَهُ‏.‏ تَابَعَهُ بِشْرٌ عَنِ ابْنِ الْمُبَارَكِ، عَنْ شُعْبَةَ،‏.‏ وَتَابَعَهُ ابْنُ جُرَيْجٍ عَنْ عَبْدَةَ، عَنْ شَقِيقٍ، سَمِعْتُ عَبْدَ اللَّهِ، سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم‏.‏", chapter: "Virtues of the Qur'an", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا عَبْدُ الرَّحْمَنِ بْنُ بُوذَوَيْهِ، عَنْ مَعْمَرٍ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ، عَنِ ابْنِ عَبَّاسٍ، عَنْ مَيْمُونَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِ حَدِيثِ الزُّهْرِيِّ عَنِ ابْنِ الْمُسَيَّبِ ‏.‏", chapter: "Foods (Kitab Al-At'imah)", ref: "Abudawud · Unknown" },
  { arabic: "وَحَدَّثَنِي أَحْمَدُ بْنُ مَنِيعٍ، وَيَعْقُوبُ الدَّوْرَقِيُّ، قَالاَ حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا مَنْصُورٌ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، - رضى الله عنها - قَالَتْ كُنْتُ أُطَيِّبُ النَّبِيَّ صلى الله عليه وسلم قَبْلَ أَنْ يُحْرِمَ وَيَوْمَ النَّحْرِ قَبْلَ أَنْ يَطُوفَ بِالْبَيْتِ بِطِيبٍ فِيهِ مِسْكٌ ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى الأَزْدِيُّ، حَدَّثَنَا مُوسَى بْنُ دَاوُدَ، وَخَالِدُ بْنُ أَبِي يَزِيدَ، قَالاَ حَدَّثَنَا أَبُو بَكْرٍ الْمَدَنِيُّ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ قَالَ ‏\n\"‏ إِذَا نَزَلَ الرَّجُلُ بِقَوْمٍ فَلاَ يَصُومُ إِلاَّ بِإِذْنِهِمْ ‏\"‏ ‏.‏", chapter: "Fasting", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، قَالَ حَدَّثَنَا خَالِدٌ، عَنْ أَبِي قِلاَبَةَ، عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ إِذَا حَضَرَتِ الصَّلاَةُ فَأَذِّنَا وَأَقِيمَا، ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا ‏\"‏‏.‏", chapter: "Call to Prayers (Adhaan)", ref: "Buhari · Unknown" },
  { arabic: "وَحَدَّثَنَاهُ مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدٌ، - يَعْنِي ابْنَ جَعْفَرٍ - حَدَّثَنَا شُعْبَةُ، بِهَذَا الإِسْنَادِ غَيْرَ أَنَّهُ قَالَ وَكَانَ مِمَّنْ لَمْ يَكُنْ مَعَهُ الْهَدْىُ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ وَرَجُلٌ آخَرُ فَأَحَلاَّ ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عَاصِمِ بْنِ أَبِي النَّجُودِ، عَنْ شَقِيقٍ، عَنْ عَبْدِ اللَّهِ، قَالَ كُنَّا نَعُدُّ الْمَاعُونَ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم عَارِيَةَ الدَّلْوِ وَالْقِدْرِ ‏.‏", chapter: "Zakat (Kitab Al-Zakat)", ref: "Abudawud · Unknown" },
  { arabic: "وَحَدَّثَنِيهِ زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ، حَدَّثَنَا هَمَّامٌ، حَدَّثَنَا \n إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِهِ\n غَيْرَ أَنَّهُ قَالَ كَانَ لاَ يَدْخُلُ ‏.", chapter: "The Book on Government", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو الْوَلِيدِ الطَّيَالِسِيُّ، حَدَّثَنَا هَمَّامٌ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ سَمُرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا وَنِعْمَتْ وَمَنِ اغْتَسَلَ فَهُوَ أَفْضَلُ ‏\"‏ ‏.‏", chapter: "Purification (Kitab Al-Taharah)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الْحَسَنِ بْنِ عَمْرٍو، عَنْ مُجَاهِدٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ مَنْ قَتَلَ مُعَاهِدًا لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا ‏\"‏ ‏.‏", chapter: "The Chapters on Blood Money", ref: "Ibnmajah · Unknown" },
  { arabic: "عَنِ ابْنِ عُمَرَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ إِذَا اعْتَكَفَ طُرِحَ لَهُ فِرَاشُهُ أَوْ يُوضَعُ لَهُ سَرِيرُهُ وَرَاءَ أسطوانه التَّوْبَة. رَوَاهُ ابْن مَاجَه", chapter: "Fasting", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ حُمَيْدٍ  ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُخْتَارٍ  ، عَنْ مُحَمَّدِ بْنِ إِسْحَاق  ، عَنْ عَمِّهِ عَبْدِ الرَّحْمَنِ بْنِ يَسَارٍ  ، عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ  ، عَنْ أبِيهِ  ، عَنْ عَلِيٍّ  ، قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :\" إِذَا كَانَ ثُلُثُ اللَّيْلِ أَوْ نِصْفُ اللَّيْلِ \" فَذَكَرَ النُّزُولَ", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، أَنَّ سَعِيدَ بْنَ الْمُسَيَّبِ، سُئِلَ عَنِ الْمَرْأَةِ، يُطَلِّقُهَا زَوْجُهَا وَهِيَ فِي بَيْتٍ بِكِرَاءٍ عَلَى مَنِ الْكِرَاءُ فَقَالَ سَعِيدُ بْنُ الْمُسَيَّبِ عَلَى زَوْجِهَا ‏.‏ قَالَ فَإِنْ لَمْ يَكُنْ عِنْدَ زَوْجِهَا قَالَ فَعَلَيْهَا ‏.‏ قَالَ فَإِنْ لَمْ يَكُنْ عِنْدَهَا قَالَ فَعَلَى الأَمِيرِ ‏.‏", chapter: "Divorce", ref: "Malik · Unknown" },
  { arabic: "أَخْبَرَنَا أَبُو بَكْرِ بْنُ نَافِعٍ، قَالَ حَدَّثَنَا بَهْزُ بْنُ أَسَدٍ، قَالَ حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَقُولُ ‏\n\"‏ اسْتَوُوا اسْتَوُوا اسْتَوُوا فَوَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لأَرَاكُمْ مِنْ خَلْفِي كَمَا أَرَاكُمْ مِنْ بَيْنِ يَدَىَّ ‏\"‏ ‏.‏", chapter: "The Book of Leading the Prayer (Al-Imamah)", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا النُّفَيْلِيُّ، حَدَّثَنَا عِيسَى، - يَعْنِي ابْنَ يُونُسَ - عَنْ سَعِيدِ بْنِ أَبِي عَرُوبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، قَالَ رَخَّصَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ وَلِلزُّبَيْرِ بْنِ الْعَوَّامِ فِي قُمُصِ الْحَرِيرِ فِي السَّفَرِ مِنْ حِكَّةٍ كَانَتْ بِهِمَا ‏.‏", chapter: "Clothing (Kitab Al-Libas)", ref: "Abudawud · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، قَالَ حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ دَاوُدَ، قَالَ سَأَلْتُ سَعِيدًا مَا الشَّرَابُ الَّذِي أَحَلَّهُ عُمَرُ رضى الله عنه قَالَ الَّذِي يُطْبَخُ حَتَّى يَذْهَبَ ثُلُثَاهُ وَيَبْقَى ثُلُثُهُ ‏.‏", chapter: "The Book of Drinks", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو مَعْمَرٍ، حَدَّثَنَا عَبْدُ الْوَارِثِ، حَدَّثَنَا يُونُسُ، عَنْ حُمَيْدِ بْنِ هِلاَلٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\n\"‏ إِذَا مَرَّ بَيْنَ يَدَىْ أَحَدِكُمْ شَىْءٌ وَهُوَ يُصَلِّي فَلْيَمْنَعْهُ، فَإِنْ أَبَى فَلْيَمْنَعْهُ، فَإِنْ أَبَى فَلْيُقَاتِلْهُ، فَإِنَّمَا هُوَ شَيْطَانٌ ‏\"‏‏.‏", chapter: "Beginning of Creation", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا مُعْتَمِرٌ، عَنْ حُمَيْدٍ، عَنْ أَنَسٍ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا ‏\"‏‏.‏ قَالُوا يَا رَسُولَ اللَّهِ هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا قَالَ ‏\"‏ تَأْخُذُ فَوْقَ يَدَيْهِ ‏\"‏‏.‏", chapter: "Oppressions", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ عُبَيْدِ اللَّهِ، قَالَ حَدَّثَنِي سَعِيدُ بْنُ أَبِي سَعِيدٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ تُنْكَحُ الْمَرْأَةُ لأَرْبَعٍ لِمَالِهَا وَلِحَسَبِهَا وَجَمَالِهَا وَلِدِينِهَا، فَاظْفَرْ بِذَاتِ الدِّينِ تَرِبَتْ يَدَاكَ ‏\"‏‏.‏", chapter: "Wedlock, Marriage (Nikaah)", ref: "Buhari · Unknown" },
  { arabic: "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَلِيُّ بْنُ حَفْصٍ، حَدَّثَنَا شُعْبَةُ، عَنْ خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ حَفْصِ بْنِ عَاصِمٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِ ذَلِكَ ‏.‏", chapter: "Introduction", ref: "Muslim · Unknown" },
  { arabic: "وَعَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ قَالَ حَمَلْتُ حَجَرًا ثقيلاً فَبينا أَنَا أَمْشِي سَقَطَ عَنِّي ثَوْبِي فَلَمْ أَسْتَطِعْ أَخْذَهُ فَرَآنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: «خُذْ عَلَيْكَ ثَوْبَكَ وَلَا تَمْشُوا عُرَاة» . رَوَاهُ مُسلم", chapter: "Marriage", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا أَبُو شِهَابٍ، عَنِ الْحَذَّاءِ، عَنْ أَبِي الْمُتَوَكِّلِ النَّاجِيِّ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ مَا كُنَّا نَكْتُبُ غَيْرَ التَّشَهُّدِ وَالْقُرْآنِ ‏.‏", chapter: "Knowledge (Kitab Al-Ilm)", ref: "Abudawud · Unknown" },
  { arabic: "أَخْبَرَنَا يَحْيَى بْنُ حَسَّانَ  ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ  ، وَسُلَيْمَانُ بْنُ كَثِيرٍ  ، عَنْ الزُّهْرِيِّ  ، عَنْ أَنَسِ بْنِ مَالِكٍ  ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ :\" إِذَا حَضَرَ الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ، فَابْدَءُوا بِالْعَشَاءِ \"", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "وَعَنِ ابْنِ عَبَّاسٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَرْمُلْ فِي السَّبْعِ الَّذِي أَفَاضَ فِيهِ. رَوَاهُ أَبُو دَاوُدَ وَابْنُ مَاجَهْ", chapter: "The Rites of Pilgrimage", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا هَنَّادُ بْنُ السَّرِيِّ، عَنْ أَبِي الأَحْوَصِ، عَنْ مَنْصُورٍ، عَنْ رِبْعِيِّ بْنِ حِرَاشٍ، قَالَ حُدِّثْتُ أَنَّ رَجُلاً مِنْ بَنِي عَامِرٍ اسْتَأْذَنَ عَلَى النَّبِيِّ صلى الله عليه وسلم بِمَعْنَاهُ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَلِكَ حَدَّثَنَا مُسَدَّدٌ حَدَّثَنَا أَبُو عَوَانَةَ عَنْ مَنْصُورٍ عَنْ رِبْعِيٍّ وَلَمْ يَقُلْ عَنْ رَجُلٍ مِنْ بَنِي عَامِرٍ ‏.‏", chapter: "General Behavior (Kitab Al-Adab)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ عَبْدَةَ، وَإِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ أَبُو مَعْمَرٍ الْهُذَلِيُّ، عَنْ سُفْيَانَ، عَنْ عَمْرٍو، عَنْ عِكْرِمَةَ، قَالَ حَدَّثَنَا أَبُو هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم - قَالَ إِسْمَاعِيلُ عَنْ أَبِي هُرَيْرَةَ رِوَايَةً - فَذَكَرَ حَدِيثَ الْوَحْىِ قَالَ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏ حَتَّى إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ ‏}‏ ‏.‏", chapter: "Dialects and Readings of the Qur'an (Kitab Al-Huruf Wa Al-Qira'at)", ref: "Abudawud · Unknown" },
  { arabic: "أَخْبَرَنِي إِبْرَاهِيمُ بْنُ يَعْقُوبَ، قَالَ حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى، قَالَ حَدَّثَنَا شَيْبَانُ، عَنْ يَحْيَى، عَنْ مُحَمَّدِ بْنِ الزُّبَيْرِ، عَنْ أَبِيهِ، عَنْ عِمْرَانَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ لاَ نَذْرَ فِي غَضَبٍ وَكَفَّارَتُهُ كَفَّارَةُ الْيَمِينِ ‏\"‏ ‏.‏", chapter: "The Book of Oaths and Vows", ref: "Nasai · Unknown" },
  { arabic: "وَحَدَّثَنِيهِ أَحْمَدُ الدَّارِمِيُّ، حَدَّثَنَا زَكَرِيَّاءُ بْنُ عَدِيٍّ، حَدَّثَنَا يَزِيدُ، - يَعْنِي ابْنَ زُرَيْعٍ - عَنْ رَوْحِ بْنِ الْقَاسِمِ، حَدَّثَنَا أَيُّوبُ بْنُ مُوسَى، بِهَذَا الإِسْنَادِ وَقَالَ أَفَأَحُلُّهُ فَأَغْسِلُهُ مِنَ الْجَنَابَةِ ‏.‏ وَلَمْ يَذْكُرِ الْحَيْضَةَ ‏.‏", chapter: "The Book of Menstruation", ref: "Muslim · Unknown" },
  { arabic: "وعن عائشة رضي الله عنها، قالت‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏إن الله وملائكته يصلون على ميامن الصفوف‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد على شرط مسلم، وفيه رجل مختلف في توثيقه‏.‏ ‏)‏‏)‏‏.‏", chapter: "The Book of Virtues", ref: "Riyad Assalihin · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ ‏:‏ لَمَّا مَاتَ النَّجَاشِيُّ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏:‏ ‏\n\"‏ اسْتَغْفِرُوا لَهُ ‏\"‏ ‏.‏", chapter: "The Book of Funerals", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا يَعْقُوبُ، عَنْ مُوسَى بْنِ عُقْبَةَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ إِذَا طَافَ فِي الْحَجِّ وَالْعُمْرَةِ أَوَّلَ مَا يَقْدَمُ فَإِنَّهُ يَسْعَى ثَلاَثَةَ أَطْوَافٍ وَيَمْشِي أَرْبَعًا ثُمَّ يُصَلِّي سَجْدَتَيْنِ ثُمَّ يَطُوفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ ‏.‏", chapter: "The Book of Hajj", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنِي مُحَمَّدُ بْنُ يَحْيَى بْنِ مُحَمَّدٍ، قَالَ حَدَّثَنَا الْحَسَنُ بْنُ الرَّبِيعِ، قَالَ حَدَّثَنَا أَبُو الأَحْوَصِ، عَنِ الأَعْمَشِ، عَنْ أَبِي وَائِلٍ، عَنْ أَبِي نُخَيْلَةَ، عَنْ جَرِيرٍ، قَالَ أَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرَ نَحْوَهُ ‏.‏", chapter: "The Book of al-Bay'ah", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى، قَالَ‏:‏ حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ زِيَادِ بْنِ مِخْرَاقٍ، عَنْ طَيْسَلَةَ، أَنَّهُ سَمِعَ ابْنَ عُمَرَ يَقُولُ‏:‏ بُكَاءُ الْوَالِدَيْنِ مِنَ الْعُقُوقِ وَالْكَبَائِرِ‏.‏", chapter: "Parents", ref: "Aladab Almufrad · Unknown" },
  { arabic: "وَحَدَّثَنِي حَرْمَلَةُ بْنُ يَحْيَى، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِيهِ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُسَبِّحُ عَلَى الرَّاحِلَةِ قِبَلَ أَىِّ وَجْهٍ تَوَجَّهَ وَيُوتِرُ عَلَيْهَا غَيْرَ أَنَّهُ لاَ يُصَلِّي عَلَيْهَا الْمَكْتُوبَةَ ‏.‏", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ سَالِمٍ، عَنْ أَبِيهِ، قَالَ حَدَّثَنِي زَيْدُ بْنُ ثَابِتٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم رَخَّصَ فِي الْعَرَايَا ‏.‏", chapter: "The Book of Financial Transactions", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو مَعْمَرٍ، حَدَّثَنَا عَبْدُ الْوَارِثِ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسِ بْنِ مَالِكٍ ـ رضى الله عنه ـ قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَتَعَوَّذُ يَقُولُ ‏\n\"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ مِنَ الْهَرَمِ، وَأَعُوذُ بِكَ مِنَ الْبُخْلِ ‏\"‏‏.‏", chapter: "Invocations", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنِي أَبِي، عَنْ إِسْمَاعِيلَ بْنِ سُمَيْعٍ، عَنْ مُسْلِمٍ،\n الْبَطِينِ عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم\n ‏\n\"‏ مَنْ سَمَّعَ سَمَّعَ اللَّهُ بِهِ وَمَنْ رَاءَى رَاءَى اللَّهُ بِهِ ‏\"‏ ‏.‏", chapter: "The Book of Zuhd and Softening of Hearts", ref: "Muslim · Unknown" },
  { arabic: "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، عَنْ سُفْيَانَ، قَالَ أَبُو بَكْرٍ وَحَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، عَنْ زَكَرِيَّاءَ، كِلاَهُمَا عَنْ سِمَاكٍ، عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ إِذَا صَلَّى الْفَجْرَ جَلَسَ فِي مُصَلاَّهُ حَتَّى تَطْلُعَ الشَّمْسُ حَسَنًا ‏.‏", chapter: "The Book of Mosques and Places of Prayer", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَاهُ مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا مَكِّيٌّ، قَالَ يَزِيدُ أَخْبَرَنَا قَالَ كَانَ سَلَمَةُ يَتَحَرَّى الصَّلاَةَ عِنْدَ الأُسْطُوَانَةِ الَّتِي عِنْدَ الْمُصْحَفِ فَقُلْتُ لَهُ يَا أَبَا مُسْلِمٍ أَرَاكَ تَتَحَرَّى الصَّلاَةَ عِنْدَ هَذِهِ الأُسْطُوَانَةِ ‏.‏ قَالَ رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يَتَحَرَّى الصَّلاَةَ عِنْدَهَا ‏.‏", chapter: "The Book of Prayers", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا إِسْحَاقُ بْنُ سُلَيْمَانَ، عَنْ أَبِي جَعْفَرٍ الرَّازِيِّ، عَنْ حُصَيْنٍ، عَنِ الشَّعْبِيِّ، عَنْ بُرَيْدَةَ بْنِ الْحُصَيْبِ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ لاَ رُقْيَةَ إِلاَّ مِنْ عَيْنٍ أَوْ حُمَةٍ ‏\"‏ ‏.‏", chapter: "Chapters on Medicine", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا حَامِدُ بْنُ يَحْيَى، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا وَائِلُ بْنُ دَاوُدَ، عَنِ ابْنِهِ، بَكْرِ بْنِ وَائِلٍ عَنِ الزُّهْرِيِّ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم أَوْلَمَ عَلَى صَفِيَّةَ بِسَوِيقٍ وَتَمْرٍ ‏.‏", chapter: "Foods (Kitab Al-At'imah)", ref: "Abudawud · Unknown" },
  { arabic: "وعنه رضي الله عنه قال‏:‏ شهدت من النبي صلى الله عليه وسلم  مجلساً وصف فيه الجنة حتى انتهى، ثم قال في آخر حديثه‏:‏ ‏\n\"‏فيها مالا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر‏\"‏ ثم قرأ ‏{‏تتجافى جنوبهم عن المضاجع‏}‏ إلى قوله تعالى‏:‏ ‏{‏فلا تعلم نفس ما أخفي لهم من قرة أعين‏}‏‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏", chapter: "The Book of Forgiveness", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، أَنَّ رَجُلاً، جَاءَهُ الْمَوْتُ فِي زَمَانِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ رَجُلٌ هَنِيئًا لَهُ مَاتَ وَلَمْ يُبْتَلَ بِمَرَضٍ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ وَيْحَكَ وَمَا يُدْرِيكَ لَوْ أَنَّ اللَّهَ ابْتَلاَهُ بِمَرَضٍ يُكَفِّرُ بِهِ مِنْ سَيِّئَاتِهِ ‏\"‏ ‏.‏", chapter: "The Evil Eye", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا يَحْيَى بْنُ حَمْزَةَ، حَدَّثَنِي ثَوْرُ بْنُ يَزِيدَ، عَنْ خَالِدِ بْنِ مَعْدَانَ، عَنْ رَبِيعَةَ بْنِ الْغَازِ، أَنَّهُ سَأَلَ عَائِشَةَ عَنْ صِيَامِ، رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَقَالَتْ كَانَ يَتَحَرَّى صِيَامَ الاِثْنَيْنِ وَالْخَمِيسِ ‏.‏", chapter: "Fasting", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، عَنِ النَّهَّاسِ بْنِ قَهْمٍ، عَنْ شَدَّادٍ أَبِي عَمَّارٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ مَنْ حَافَظَ عَلَى شُفْعَةِ الضُّحَى غُفِرَتْ لَهُ ذُنُوبُهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ ‏\"‏ ‏.‏", chapter: "Establishing the Prayer and the Sunnah Regarding Them", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، أَخْبَرَنَا حِبَّانُ بْنُ هِلاَلٍ، حَدَّثَنَا هَمَّامٌ، حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ نَعْلاَهُ لَهُمَا قِبَالاَنِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ قَالَ وَفِي الْبَابِ عَنِ ابْنِ عَبَّاسٍ وَأَبِي هُرَيْرَةَ ‏.‏", chapter: "The Book on Clothing", ref: "Tirmidhi · Unknown" },
  { arabic: "حَدَّثَنَا عَبْد اللَّهِ، حَدَّثَنِي عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا شَرِيكٌ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَاصِمِ بْنِ ضَمْرَةَ، قَالَ قُلْتُ لِلْحَسَنِ بْنِ عَلِيٍّ إِنَّ الشِّيعَةَ يَزْعُمُونَ أَنَّ عَلِيًّا، رَضِيَ اللَّهُ عَنْهُ يَرْجِعُ قَالَ كَذَبَ أُولَئِكَ الْكَذَّابُونَ لَوْ عَلِمْنَا ذَاكَ مَا تَزَوَّجَ نِسَاؤُهُ وَلَا قَسَمْنَا مِيرَاثَهُ‏.‏", chapter: "Musnad 'Ali Ibn Abi Talib", ref: "Ahmed · Unknown" },
  { arabic: "عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لِيَسْأَلْ أَحَدُكُمْ رَبَّهُ حَاجَتَهُ كُلَّهَا حَتَّى يَسْأَلَهُ شِسْعَ نَعله إِذا انْقَطع»\nزَادَ فِي رِوَايَةٍ عَنْ ثَابِتٍ الْبُنَانِيِّ مُرْسَلًا «حَتَّى يَسْأَلَهُ الْمِلْحَ وَحَتَّى يَسْأَلَهُ شِسْعَهُ إِذَا انْقَطع» . رَوَاهُ التِّرْمِذِيّ", chapter: "Supplications", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، عَنْ هُشَيْمٍ، عَنْ عَبَّادِ بْنِ، أَبِي صَالِحٍ عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ الْيَمِينُ عَلَى نِيَّةِ الْمُسْتَحْلِفِ ‏\"‏ ‏.‏", chapter: "The Book of Oaths", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا أَبُو دَاوُدَ، حَدَّثَنَا شُعْبَةُ، عَنْ عَاصِمٍ الأَحْوَلِ، عَنْ أَبِي حَاجِبٍ، عَنِ الْحَكَمِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ نَهَى أَنْ يَتَوَضَّأَ الرَّجُلُ بِفَضْلِ وَضُوءِ الْمَرْأَةِ ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "عن أنس رضي الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم  أن يبيع حاضر لباد وإن كان أخاه لأبيه وأمه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، وَهَارُونُ بْنُ عَبْدِ اللَّهِ، قَالاَ حَدَّثَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، قَالَ قَالَ ابْنُ جُرَيْجٍ أَخْبَرَنِي عُثْمَانُ بْنُ أَبِي سُلَيْمَانَ، أَنَّ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ، أَخْبَرَهُ أَنَّ عَائِشَةَ أَخْبَرَتْهُ أَنَّ النَّبِيَّ صلى الله عليه وسلم لَمْ يَمُتْ حَتَّى كَانَ كَثِيرٌ مِنْ صَلاَتِهِ وَهُوَ جَالِسٌ ‏.‏", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا الْمُعَلَّى بْنُ أَسَدٍ حَدَّثَنَا أَبُو عَوَانَةَ ، عَنْ مُغِيرَةَ ، عَنْ إِبْرَاهِيمَ ، قَالَ :\" لَا بَأْسَ أَنْ تَتَنَاوَلَ الْحَائِضُ مِنْ الْمَسْجِدِ الشَّيْءَ \"", chapter: "كِتَاب الطَّهَارَةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ الْمُخْتَارِ، عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ ‏\"‏ ‏.‏", chapter: "Chapters Regarding Funerals", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا عَمْرُو بْنُ عَلِيٍّ، قَالَ حَدَّثَنَا يَحْيَى، عَنْ إِسْمَاعِيلَ، عَنْ عَامِرٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\n\"‏ الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏\"‏ ‏.‏", chapter: "The Book Of Faith and its Signs", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَمَرَ بِصِيَامِ يَوْمِ عَاشُورَاءَ، فَلَمَّا فُرِضَ رَمَضَانُ كَانَ مَنْ شَاءَ صَامَ، وَمَنْ شَاءَ أَفْطَرَ‏.‏", chapter: "Fasting", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنْ مُسَاوِرٍ الْوَرَّاقِ، عَنْ جَعْفَرِ بْنِ عَمْرِو بْنِ حُرَيْثٍ، عَنْ أَبِيهِ، قَالَ رَأَيْتُ عَلَى النَّبِيِّ صلى الله عليه وسلم عِمَامَةً حَرْقَانِيَّةً ‏.‏", chapter: "The Book of Adornment", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ مَا\n خُيِّرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَيْنَ أَمْرَيْنِ أَحَدُهُمَا أَيْسَرُ مِنَ الآخَرِ إِلاَّ اخْتَارَ أَيْسَرَهُمَا\n مَا لَمْ يَكُنْ إِثْمًا فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ ‏.‏", chapter: "The Book of Virtues", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّ عَائِشَةَ ـ رضى الله عنها ـ زَوْجَ النَّبِيِّ صلى الله عليه وسلم قَالَتْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ مَا مِنْ مُصِيبَةٍ تُصِيبُ الْمُسْلِمَ إِلاَّ كَفَّرَ اللَّهُ بِهَا عَنْهُ، حَتَّى الشَّوْكَةِ يُشَاكُهَا ‏\"‏‏.‏", chapter: "Patients", ref: "Buhari · Unknown" },
  { arabic: "وَعَنْهَا قَالَتْ: { جَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ.‏ فَقَالَتْ: يَا رَسُولَ اَللَّهِ! إِنَّ سَالِمًا مَوْلَى أَبِي حُذَيْفَةَ مَعَنَا فِي بَيْتِنَا, وَقَدْ بَلَغَ مَا يَبْلُغُ اَلرِّجَالُ.‏ قَالَ: \n\"أَرْضِعِيهِ.‏ تَحْرُمِي عَلَيْهِ\".‏ }  رَوَاهُ مُسْلِمٌ  1‏ .‏‏1 ‏- صحيح.‏ رواه مسلم (1453)‏ (27)‏.‏", chapter: "Marriage", ref: "Bulugh Almaram · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيٌّ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا أَبُو الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ لاَ تَقُومُ السَّاعَةُ حَتَّى تَقْتَتِلَ فِئَتَانِ دَعْوَاهُمَا وَاحِدَةٌ ‏\"‏‏.‏", chapter: "Apostates", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ مَنْصُورٍ، قَالَ حَدَّثَنَا سُفْيَانُ، قَالَ حَدَّثَنَا عُثْمَانُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، قَالَ قُلْتُ لِعَائِشَةَ بِأَىِّ شَىْءٍ طَيَّبْتِ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَتْ بِأَطْيَبِ الطِّيبِ عِنْدَ حُرْمِهِ وَحِلِّهِ ‏.‏", chapter: "The Book of Hajj", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا هَمَّامٌ، عَنْ قَتَادَةَ، عَنْ أَبِي الْمَلِيحِ، عَنْ أَبِيهِ، أَنَّ يَوْمَ، حُنَيْنٍ كَانَ يَوْمَ مَطَرٍ فَأَمَرَ النَّبِيُّ صلى الله عليه وسلم مُنَادِيَهُ أَنِ الصَّلاَةُ فِي الرِّحَالِ ‏.‏", chapter: "Prayer (Kitab Al-Salat)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا سُفْيَانُ، عَنْ أَبِي إِسْحَاقَ، عَنِ الْحَارِثِ، عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ قَالَ قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالدَّيْنِ قَبْلَ الْوَصِيَّةِ وَأَنْتُمْ تَقْرَءُونَ ‏{‏مِنْ بَعْدِ وَصِيَّةٍ يُوصَى بِهَا أَوْ دَيْنٍ‏}‏ وَإِنَّ أَعْيَانَ بَنِي الْأُمِّ يَتَوَارَثُونَ دُونَ بَنِي الْعَلَّاتِ‏.‏", chapter: "Musnad 'Ali Ibn Abi Talib", ref: "Ahmed · Unknown" },
  { arabic: "وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\"‏تُفتح أبواب الجنة يوم الاثنين ويوم الخميس، فيغفر لكل عبد لا يشرك بالله شيئًا، إلا رجلا كانت بينه وبين أخيه شحناء فيقال‏:‏ أنظروا هذين حتى يصطلحا‏!‏ أنظروا هذين حتى يصطلحا‏!‏‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏ وفي رواية له ‏\"‏تعرض الأعمال في كل يوم خميس واثنين‏\"‏ وذكر نحوه‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَعَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِذَا صَلَّى أَحَدُكُمْ فَلْيَجْعَلْ تِلْقَاءَ وَجْهِهِ شَيْئًا فَإِنْ لَمْ يَجِدْ فَلْيَنْصِبْ عَصَاهُ فَإِنْ لَمْ يَكُنْ مَعَهُ عَصَى فَلْيَخْطُطْ خَطًّا ثُمَّ لَا يَضُرُّهُ مَا مَرَّ أَمَامه» . رَوَاهُ أَبُو دَاوُد وَابْن مَاجَه", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا عَبْد اللَّهِ، حَدَّثَنَا عَلِيُّ بْنُ حَكِيمٍ الْأَوْدِيُّ، أَنْبَأَنَا شَرِيكٌ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَاصِمِ بْنِ ضَمْرَةَ، عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ قَالَ الْوَتْرُ لَيْسَ بِحَتْمٍ وَلَكِنَّهُ سُنَّةٌ سَنَّهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ‏.‏", chapter: "Musnad 'Ali Ibn Abi Talib", ref: "Ahmed · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ أَيُّوبَ، عَنِ ابْنِ سِيرِينَ، قَالَ سَمِعْتُ أَبَا هُرَيْرَةَ، يَقُولُ قَالَ أَبُو الْقَاسِمِ صلى الله عليه وسلم ‏\n\"‏ سَمُّوا بِاسْمِي، وَلاَ تَكْتَنُوا بِكُنْيَتِي ‏\"‏", chapter: "Virtues and Merits of the Prophet (pbuh) and his Companions", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى، حَدَّثَنَا ثَابِتُ بْنُ يَزِيدَ، حَدَّثَنَا عَاصِمٌ، عَنِ الشَّعْبِيِّ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ قُمْتُ لَيْلَةً أُصَلِّي عَنْ يَسَارِ النَّبِيِّ صلى الله عليه وسلم فَأَخَذَ بِيَدِي أَوْ بِعَضُدِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ، وَقَالَ بِيَدِهِ مِنْ وَرَائِي‏.‏", chapter: "Call to Prayers (Adhaan)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنِي عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الدَّارِمِيُّ، أَخْبَرَنَا يَحْيَى بْنُ حَسَّانَ، أَخْبَرَنَا سُلَيْمَانُ،\n بْنُ بِلاَلٍ عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ\n ‏\n\"‏ نِعْمَ الأُدُمُ - أَوِ الإِدَامُ - الْخَلُّ ‏\"‏ ‏.‏", chapter: "The Book of Drinks", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا هِشَامٌ الدَّسْتَوَائِيُّ، عَنْ يَحْيَى، عَنْ أَبِي جَعْفَرٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\n\"‏ ثَلاَثُ دَعَوَاتٍ مُسْتَجَابَاتٌ لاَ شَكَّ فِيهِنَّ دَعْوَةُ الْوَالِدِ وَدَعْوَةُ الْمُسَافِرِ وَدَعْوَةُ الْمَظْلُومِ ‏\"‏ ‏.‏", chapter: "Prayer (Kitab Al-Salat): Detailed Injunctions about Witr", ref: "Abudawud · Unknown" },
  { arabic: "عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ أَبِيهِ عَنْ جَدِّهِ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «الْبَيِّنَةُ عَلَى الْمُدَّعِي وَالْيَمِينُ عَلَى الْمُدَّعَى عَلَيْهِ» . رَوَاهُ التِّرْمِذِيّ", chapter: "The Offices of Commander and Qadi", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا إِسْحَاقُ بْنُ سَعِيدِ بْنِ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ، عَنْ أَبِيهِ، سَعِيدٍ عَنِ ابْنِ عُمَرَ، قَالَ لَقَدْ رَأَيْتُنِي مَعَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ بَنَيْتُ بَيْتًا يُكِنُّنِي مِنَ الْمَطَرِ وَيُكِنُّنِي مِنَ الشَّمْسِ مَا أَعَانَنِي عَلَيْهِ خَلْقُ اللَّهِ تَعَالَى ‏.‏", chapter: "Zuhd", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا الْعَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ الْعَنْبَرِيُّ، حَدَّثَنَا عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ، حَدَّثَنِي شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ الأَسْنَانُ سَوَاءٌ الثَّنِيَّةُ وَالضِّرْسُ سَوَاءٌ ‏\"‏ ‏.‏", chapter: "The Chapters on Blood Money", ref: "Ibnmajah · Unknown" },
  { arabic: "وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، قَالَ قَرَأْتُ عَلَى مَالِكٍ عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنِ ابْنِ، عُمَرَ - رضى الله عنهما - عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي السَّبْعِ الأَوَاخِرِ ‏\"‏ ‏.‏", chapter: "The Book of Fasting", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا حَمَّادٌ، عَنْ خُثَيْمِ بْنِ عِرَاكِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\n\"‏ لَيْسَ عَلَى الْمُسْلِمِ صَدَقَةٌ فِي غُلاَمِهِ وَلاَ فِي فَرَسِهِ ‏\"‏ ‏.‏", chapter: "The Book of Zakah", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا عَبِيدَةُ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنْ أَنَسٍ، قَالَ بَالَ أَعْرَابِيٌّ فِي الْمَسْجِدِ فَأَمَرَ النَّبِيُّ صلى الله عليه وسلم بِدَلْوٍ مِنْ مَاءٍ فَصُبَّ عَلَيْهِ ‏.‏", chapter: "The Book of Purification", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنِي مُحَمَّدُ بْنُ آدَمَ بْنِ سُلَيْمَانَ، عَنِ ابْنِ الْمُبَارَكِ، عَنِ ابْنِ أَبِي ذِئْبٍ، عَنْ سَعِيدٍ الْمَقْبُرِيِّ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ إِنَّكُمْ سَتَحْرِصُونَ عَلَى الإِمَارَةِ وَإِنَّهَا سَتَكُونُ نَدَامَةً وَحَسْرَةً فَنِعْمَتِ الْمُرْضِعَةُ وَبِئْسَتِ الْفَاطِمَةُ ‏\"‏ ‏.‏", chapter: "The Book of al-Bay'ah", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ، عَنْ أَبِيهِ، عَنْ مُسْلِمِ بْنِ قُرْطٍ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْغَائِطِ فَلْيَذْهَبْ مَعَهُ بِثَلاَثَةِ أَحْجَارٍ فَلْيَسْتَطِبْ بِهَا فَإِنَّهَا تَجْزِي عَنْهُ ‏\"‏ ‏.‏", chapter: "The Book of Purification", ref: "Nasai · Unknown" },
  { arabic: "وَعَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِذَا انْقَطَعَ شِسْعُ نَعْلِهِ فَلَا يَمْشِ فِي نَعْلٍ وَاحِدَةٍ حَتَّى يُصْلِحَ شِسْعَهُ وَلَا يَمْشِ فِي خُفٍّ وَاحِدٍ وَلَا يأكلْ بِشمَالِهِ وَلَا يجتبي بِالثَّوْبِ الْوَاحِدِ وَلَا يَلْتَحِفِ الصَّمَّاءَ» . رَوَاهُ مُسْلِمٌ", chapter: "Clothing", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو نُعَيْمٍ  ، حَدَّثَنَا فِطْرٌ  ، عَنْ أَبِي إِسْحَاق  ، عَنْ أَبِي الْأَحْوَصِ  ، عَنْ عَبْدِ اللَّهِ  ، قَالَ :\" مَنْ قَرَأَ فِي لَيْلَةٍ بِمِائَةِ آيَةٍ، كُتِبَ مِنْ الْقَانِتِينَ \"", chapter: "وَمِنْ كِتَابِ فَضَائِلِ الْقُرْآنِ", ref: "Darimi · Unknown" },
  { arabic: "وَعَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَا جَلَبَ وَلَا جَنَبَ» . زَادَ يَحْيَى فِي حَدِيثِهِ: «فِي الرِّهَانِ» . رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَرَوَاهُ التِّرْمِذِيُّ مَعَ زِيَادَة فِي بَاب «الْغَضَب»", chapter: "Jihad", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ آدَمَ، عَنْ حَفْصٍ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم سَلَّمَ ثُمَّ تَكَلَّمَ ثُمَّ سَجَدَ سَجْدَتَىِ السَّهْوِ ‏.‏", chapter: "The Book of Forgetfulness (In Prayer)", ref: "Nasai · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ رَافِعٍ، قَالَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، قَالَ أَنْبَأَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنِ ابْنِ الْمُسَيَّبِ، قَالَ كَانَتِ الْقَسَامَةُ فِي الْجَاهِلِيَّةِ ثُمَّ أَقَرَّهَا رَسُولُ اللَّهِ صلى الله عليه وسلم فِي الأَنْصَارِيِّ الَّذِي وُجِدَ مَقْتُولاً فِي جُبِّ الْيَهُودِ فَقَالَتِ الأَنْصَارُ الْيَهُودُ قَتَلُوا صَاحِبَنَا ‏.‏", chapter: "The Book of Oaths (qasamah), Retaliation and Blood Money", ref: "Nasai · Unknown" },
  { arabic: "وعن جابر رضي الله عنه عن النبي صلى الله عليه وسلم  قال‏:‏ ‏\"‏غطوا الإناء، وأوكئوا السقاء، وأغلقوا الأبواب، وأطفئوا السراج، فإن الشيطان لا يحل سقاء، ولايفتح بابًا ولايكشف إناءً، إن لم يجد أحدكم إلا أن يعرض على إنائه عودا، ويذكر اسم الله، فليفعل، فإن الفويسقة تضرم على أهل البيت بيتهم‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏ ‏\"‏الفويسقة‏:‏ الفأرة، و‏\"‏تضرم‏\"‏‏:‏ تحرق‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ إِذَا أَحْرَمَ مِنْ مَكَّةَ لَمْ يَطُفْ بِالْبَيْتِ وَلاَ بَيْنَ الصَّفَا وَالْمَرْوَةِ حَتَّى يَرْجِعَ مِنْ مِنًى وَكَانَ لاَ يَرْمُلُ إِذَا طَافَ حَوْلَ الْبَيْتِ إِذَا أَحْرَمَ مِنْ مَكَّةَ ‏.‏", chapter: "Hajj", ref: "Malik · Unknown" },
  { arabic: "عَنْ عَائِشَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْسِمُ بَيْنَ نِسَائِهِ فَيَعْدِلُ وَيَقُولُ: «اللَّهُمَّ هَذَا قَسْمِي فِيمَا أَمْلِكُ فَلَا تَلُمْنِي فِيمَا تَمْلِكُ وَلَا أَمْلِكُ» . رَوَاهُ التِّرْمِذِيُّ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ والدارمي", chapter: "Marriage", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وعن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏تنكح المرأة لأربع‏:‏ لمالها، ولحسبها، ولجمالها، ولدينها، فاظفر بذات الدين تربت يداك‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏", chapter: "The Book of Miscellany", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يَبْعَثُ بِزَكَاةِ الْفِطْرِ إِلَى الَّذِي تُجْمَعُ عِنْدَهُ قَبْلَ الْفِطْرِ بِيَوْمَيْنِ أَوْ ثَلاَثَةٍ ‏.‏", chapter: "Zakat", ref: "Malik · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ سَالِمَ بْنَ عَبْدِ اللَّهِ، وَسُلَيْمَانَ بْنَ يَسَارٍ، سُئِلاَ عَنِ الْحَائِضِ، هَلْ يُصِيبُهَا زَوْجُهَا إِذَا رَأَتِ الطُّهْرَ قَبْلَ أَنْ تَغْتَسِلَ فَقَالاَ لاَ حَتَّى تَغْتَسِلَ ‏.‏", chapter: "Purity", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، قَالَ‏:‏ أَنْبَأَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنْ قَتَادَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ‏:‏ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم احْتَجَمَ وَهُوَ مُحْرِمٌ بَمَلَلٍ عَلَى ظَهْرِ الْقَدَمِ‏.‏", chapter: "Hajaamah (Cupping-Cautering) Of Sayyidina Rasoolullah", ref: "Shamail Muhammadiyah · Unknown" },
  { arabic: "حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي أَخِي، عَنْ سُلَيْمَانَ، عَنْ ثَوْرِ بْنِ زَيْدٍ، عَنْ أَبِي الْغَيْثِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\n\"‏ الإِيمَانُ يَمَانٍ، وَالْفِتْنَةُ هَا هُنَا، هَا هُنَا يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏\"‏‏.‏", chapter: "Military Expeditions led by the Prophet (pbuh) (Al-Maghaazi)", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا زَيْدُ بْنُ الْحُبَابِ، وَقَبِيصَةُ، قَالاَ أَنْبَأَنَا سُفْيَانُ، عَنِ الضَّحَّاكِ بْنِ عُثْمَانَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ مَرَّ رَجُلٌ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ السَّلاَمَ ‏.‏", chapter: "The Book of Purification", ref: "Nasai · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ كَانَ يَكْرَهُ الإِخْصَاءَ وَيَقُولُ فِيهِ تَمَامُ الْخَلْقِ ‏.‏", chapter: "Hair", ref: "Malik · Unknown" },
  { arabic: "وَحَدَّثَنِي مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ الْمِصْرِيُّ، أَخْبَرَنَا اللَّيْثُ، ح وَحَدَّثَنَا قُتَيْبَةُ، - وَاللَّفْظُ لَهُ - قَالَ حَدَّثَنَا لَيْثٌ، عَنْ نَافِعٍ، قَالَ كَانَ ابْنُ عُمَرَ يُنِيخُ بِالْبَطْحَاءِ الَّتِي بِذِي الْحُلَيْفَةِ الَّتِي كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُنِيخُ بِهَا وَيُصَلِّي بِهَا ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "وَحَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، قَالَ الأَضْحَى يَوْمَانِ بَعْدَ يَوْمِ الأَضْحَى ‏.‏ \n وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، مِثْلُ ذَلِكَ ‏.", chapter: "Sacrificial Animals", ref: "Malik · Unknown" },
  { arabic: "وَعَنْ اِبْنِ عُمَرَ رَضِيَ اَللَّهُ عَنْهُمَا قَالَ: { قُتِلَ غُلَامٌ غِيلَةً, فَقَالَ عُمَرُ: لَوْ اِشْتَرَكَ فِيهِ أَهْلُ صَنْعَاءَ لَقَتَلْتُهُمْ بِهِ }  .‏ أَخْرَجَهُ اَلْبُخَارِيُّ  1‏‏1 ‏- صحيح.‏ رواه البخاري (6896)‏ وليس عنده لفظ: \"به\".‏", chapter: "Crimes (Qisas or Retaliation)", ref: "Bulugh Almaram · Unknown" },
  { arabic: "حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، عَنْ عُبَيْدِ اللَّهِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ نُفِسَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ بِالشَّجَرَةِ فَأَمَرَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ أَبَا بَكْرٍ أَنْ يَأْمُرَهَا أَنْ تَغْتَسِلَ وَتُهِلَّ ‏.‏", chapter: "Chapters on Hajj Rituals", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنِي سَلَمَةُ بْنُ شَبِيبٍ، حَدَّثَنَا الْحَسَنُ بْنُ مُحَمَّدِ بْنِ أَعْيَنَ، حَدَّثَنَا مَعْقِلٌ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، أَخْبَرَنِي عُمَرُ بْنُ الْخَطَّابِ، أَنَّ رَجُلاً، تَوَضَّأَ فَتَرَكَ مَوْضِعَ ظُفُرٍ عَلَى قَدَمِهِ فَأَبْصَرَهُ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\n\"‏ ارْجِعْ فَأَحْسِنْ وُضُوءَكَ ‏\"‏ ‏.‏ فَرَجَعَ ثُمَّ صَلَّى ‏.‏", chapter: "The Book of Purification", ref: "Muslim · Unknown" },
  { arabic: "وَحَدَّثَنِي سُلَيْمَانُ بْنُ مَعْبَدٍ، حَدَّثَنَا مُعَلَّى بْنُ أَسَدٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُخْتَارٍ، عَنْ عَبْدِ اللَّهِ الدَّانَاجِ، قَالَ حَدَّثَنِي أَبُو رَافِعٍ الصَّائِغُ، قَالَ سَمِعْتُ أَبَا هُرَيْرَةَ، قَالَ أَوْصَانِي خَلِيلِي أَبُو الْقَاسِمِ صلى الله عليه وسلم بِثَلاَثٍ ‏.‏ فَذَكَرَ مِثْلَ حَدِيثِ أَبِي عُثْمَانَ عَنْ أَبِي هُرَيْرَةَ ‏.‏", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ يَزِيدَ الْبَزَّازُ ، حَدَّثَنَا شَرِيكٌ ، عَنْ إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ، عَنْ مُجَاهِدٍ  : # وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُمْ مِنْ أَزْوَاجِكُمْ سورة الشعراء آية 166 #، قَالَ :\" هُوَ وَاللَّهِ الْقُبُلُ \"", chapter: "كِتَاب الطَّهَارَةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا عِيسَى بْنُ يُونُسَ، حَدَّثَنَا يُوسُفُ بْنُ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَجُلاً، قَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي مَالاً وَوَلَدًا وَإِنَّ أَبِي يُرِيدُ أَنْ يَجْتَاحَ مَالِي فَقَالَ ‏\n\"‏ أَنْتَ وَمَالُكَ لأَبِيكَ ‏\"‏ ‏.‏", chapter: "The Chapters on Business Transactions", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا إِبْرَاهِيمُ بْنُ الْمُنْذِرِ، قَالَ حَدَّثَنَا أَنَسُ بْنُ عِيَاضٍ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، أَنَّ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي الْعَصْرَ وَالشَّمْسُ لَمْ تَخْرُجْ مِنْ حُجْرَتِهَا‏.‏ وَقَالَ أَبُو أُسَامَةَ عَنْ هِشَامٍ مِنْ قَعْرِ حُجْرَتِهَا‏.‏", chapter: "Times of the Prayers", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنِ ابْنِ عُمَرَ، قَالَ كُنَّا نُبَايِعُ النَّبِيَّ صلى الله عليه وسلم عَلَى السَّمْعِ وَالطَّاعَةِ وَيُلَقِّنُنَا فِيمَا اسْتَطَعْتَ ‏.‏", chapter: "Tribute, Spoils, and Rulership (Kitab Al-Kharaj, Wal-Fai' Wal-Imarah)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ‏:‏ حَدَّثَنَا شَرِيكٌ، عَنْ عَبْدِ اللهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ، قَالَتْ‏:‏ أَتيتُ النَّبِيَّ صلى الله عليه وسلم، بِقِنَاعٍ مِنْ رُطَبٍ، وَأَجْرٍ زُغْبٍ، فَأَعْطَانِي مِلْءَ كَفِّهِ حُلِيًّا أَوْ قَالَتْ‏:‏ ذَهَبًا‏.‏", chapter: "The Fruits Eaten By Rasoolullah", ref: "Shamail Muhammadiyah · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ عُثْمَانَ النَّوْفَلِيُّ، حَدَّثَنَا أَبُو عَاصِمٍ، حَدَّثَنَا ابْنُ جُرَيْجٍ، أَخْبَرَنِي مُحَمَّدُ بْنُ يُوسُفَ، عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، أَنَّهُ سَأَلَ أُمَّ سَلَمَةَ - رضى الله عنها - عَنِ الرَّجُلِ يُصْبِحُ جُنُبًا أَيَصُومُ قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلاَمٍ ثُمَّ يَصُومُ ‏.‏", chapter: "The Book of Fasting", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ سِمَاكِ بْنِ حَرْبٍ، عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا صَلَّى الْفَجْرَ قَعَدَ فِي مُصَلاَّهُ حَتَّى تَطْلُعَ الشَّمْسُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏", chapter: "The Book on Traveling", ref: "Tirmidhi · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ مُحَمَّدٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ نُمَيْرٍ، حَدَّثَنَا عُبَيْدُ اللَّهِ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ اسْتَأْذَنَ الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ أَنْ يَبِيتَ بِمَكَّةَ أَيَّامَ مِنًى مِنْ أَجْلِ سِقَايَتِهِ فَأَذِنَ لَهُ ‏.‏", chapter: "Chapters on Hajj Rituals", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ قُدَامَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنِ الْحَكَمِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ عَبْدِ اللَّهِ بْنِ عُكَيْمٍ، قَالَ كَتَبَ إِلَيْنَا رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ أَنْ لاَ تَسْتَمْتِعُوا مِنَ الْمَيْتَةِ بِإِهَابٍ وَلاَ عَصَبٍ ‏\"‏ ‏.‏", chapter: "The Book of al-Fara' and al-'Atirah", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا وُهَيْبٌ، حَدَّثَنَا عَمْرُو بْنُ يَحْيَى، عَنْ أَبِيهِ، عَنْ أَبِي سَعِيدٍ ـ رضى الله عنه ـ قَالَ نَهَى النَّبِيُّ صلى الله عليه وسلم عَنْ صَوْمِ يَوْمِ الْفِطْرِ وَالنَّحْرِ، وَعَنِ الصَّمَّاءِ، وَأَنْ يَحْتَبِيَ الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ‏.‏ وَعَنْ صَلاَةٍ، بَعْدَ الصُّبْحِ وَالْعَصْرِ‏.‏", chapter: "Fasting", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا ابْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ - وَاللَّفْظُ لاِبْنِ الْمُثَنَّى - قَالاَ حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ،\n حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، أَنَّ نَبِيَّ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ الدَّجَّالُ\n مَكْتُوبٌ بَيْنَ عَيْنَيْهِ ك ف ر أَىْ كَافِرٌ ‏\"‏ ‏.‏", chapter: "The Book of Tribulations and Portents of the Last Hour", ref: "Muslim · Unknown" },
  { arabic: "عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّائِحَةَ وَالْمُسْتَمِعَةَ. رَوَاهُ أَبُو دَاوُد", chapter: "Funerals", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "أَخْبَرَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا حَفْصٌ، عَنْ عُبَيْدِ اللَّهِ، عَنِ الْقَاسِمِ، عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ إِذَا أَذَّنَ بِلاَلٌ فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ ‏\"‏ ‏.‏ قَالَتْ وَلَمْ يَكُنْ بَيْنَهُمَا إِلاَّ أَنْ يَنْزِلَ هَذَا وَيَصْعَدَ هَذَا ‏.‏", chapter: "The Book of the Adhan (The Call to Prayer)", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ  ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ  ، عَنْ سِمَاكِ بْنِ عَطِيَّةَ  ، عَنْ أَيُّوبَ  ، عَنْ أَبِي قِلَابَةَ  ، عَنْ أَنَسٍ  ، قَالَ :\" أُمِرَ بِلَالٌ أَنْ يَشْفَعَ الْأَذَانَ، وَيُوتِرَ الْإِقَامَةَ إِلَّا الْإِقَامَةَ \".\nأَخْبَرَنَا مُحَمَّدُ بْنُ يُوسُفَ  ، عَنْ سُفْيَانَ  ، عَنْ خَالِدٍ  عَنْ أَبِي قِلابَةَ  ، عَنْ أَنَسٍ  ، نَحْوَهُ", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ أَحْمَدَ بْنِ أَبِي خَلَفٍ  ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ  ، عَنْ عَمْرٍو  ، عَنْ الزُّهْرِيِّ  ، عَنْ سَالِمٍ  ، عَنْ أَبِيهِ  ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ\" يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ \"", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ شَقِيقِ بْنِ سَلَمَةَ، وَشَقِيقٌ، هُوَ أَبُو وَائِلٍ عَنْ قَيْسِ بْنِ أَبِي غَرَزَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ بِمَعْنَاهُ ‏.‏ قَالَ أَبُو عِيسَى وَهَذَا حَدِيثٌ صَحِيحٌ ‏.‏", chapter: "The Book on Business", ref: "Tirmidhi · Unknown" },
  { arabic: "حَدَّثَنَا بَكْرُ بْنُ خَلَفٍ أَبُو بِشْرٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنِ الْمُثَنَّى بْنِ سَعِيدٍ، عَنْ قَتَادَةَ، عَنِ ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ قَالَ ‏\n\"‏ الْمُؤْمِنُ يَمُوتُ بِعَرَقِ الْجَبِينِ ‏\"‏ ‏.‏", chapter: "Chapters Regarding Funerals", ref: "Ibnmajah · Unknown" },
  { arabic: "عَن عَمْرو بن الْعَاصِ قَالَ: أَقْرَأَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمْسُ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلَاثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَيْنِ. رَوَاهُ أَبُو دَاوُد وَابْن مَاجَه", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مَحْمُودٌ، حَدَّثَنَا عُبَيْدُ اللَّهِ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي حَصِينٍ، عَنْ مُجَاهِدٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ ‏{‏عُتُلٍّ بَعْدَ ذَلِكَ زَنِيمٍ‏}‏ قَالَ رَجُلٌ مِنْ قُرَيْشٍ لَهُ زَنَمَةٌ مِثْلُ زَنَمَةِ الشَّاةِ‏.‏", chapter: "Prophetic Commentary on the Qur'an (Tafseer of the Prophet (pbuh))", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ سَلاَمٍ، قَالَ‏:‏ أَخْبَرَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، قَالَ‏:‏ حَدَّثَنَا خَالِدٌ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ قَالَ‏:‏ مَنْ تَسَمَّعَ إِلَى حَدِيثِ قَوْمٍ وَهُمْ لَهُ كَارِهُونَ، صُبَّ فِي أُذُنِهِ الْآنُكُ‏.‏ وَمَنْ تَحَلَّمَ بِحُلْمٍ كُلِّفَ أَنْ يَعْقِدَ شَعِيرَةً‏.‏", chapter: "Behaviour with people", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنْ قَتَادَةَ، قَالَ صَلَّى الزُّبَيْرُ عَلَى عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ وَدَفَنَهُ وَكَانَ أَوْصَى إِلَيْهِ‏.‏", chapter: "Musnad Uthman ibn Affan", ref: "Ahmed · Unknown" },
  { arabic: "وَزَادَ ابْنُ مَاجَهْ مِنْ حَدِيثِ أُمِّ سَلَمَةَ: { فِي الْإِثْمِ }   1‏ .‏‏1 ‏- ضعيف.‏ رواه ابن ماجه (1617)‏، وهذه اللفظ ليست من الحديث، وإنما هي تفسير من بعض الرواة.‏", chapter: "Funerals", ref: "Bulugh Almaram · Unknown" },
  { arabic: "وَفِي رِوَايَةٍ لِأَبِي دَاوُدَ: { سَبْعَ عَشْرَةَ }   1‏ .‏‏1 ‏- هذه الرواية عند أبي داود برقم (1230)‏ وهي وإن كان إسنادها صحيحا، إلا أن رواية البخاري السابقة أرجح منها وإلى هذا أشار أبو داود، أو أن يصار إلى الجمع بين الروايتين، كما فعل البيهقي في \"المعرفة\" (4/273)‏ إذ قال: \"ويمكن الجمع بين هذه الروايات بأن يكون من قال: سبعة عشر يوما.‏ لم يعد يوم الدخول ويوم الخروج\".‏", chapter: "The Book of Prayer", ref: "Bulugh Almaram · Unknown" },
  { arabic: "وَعَن أنس قَالَ: آلى رَسُول الله مِنْ نِسَائِهِ شَهْرًا وَكَانَتِ انْفَكَّتْ رِجْلُهُ فَأَقَامَ فِي مَشْرُبَةٍ تِسْعًا وَعِشْرِينَ لَيْلَةً ثُمَّ نَزَلَ فَقَالُوا: يَا رَسُولَ اللَّهِ آلَيْتَ شَهْرًا فَقَالَ: «إِنَّ الشَّهْرَ يَكُونُ تِسْعًا وَعِشْرِينَ» . رَوَاهُ الْبُخَارِيُّ", chapter: "Marriage", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا يَحْيَى بْنُ مَعِينٍ، حَدَّثَنَا حَجَّاجٌ، عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي الأَحْوَلُ، أَنَّ طَاوُسًا، أَخْبَرَهُ عَنِ ابْنِ عَبَّاسٍ، ‏:‏ أَنَّ النَّبِيَّ صلى الله عليه وسلم مَرَّ وَهُوَ يَطُوفُ بِالْكَعْبَةِ بِإِنْسَانٍ يَقُودُهُ بِخِزَامَةٍ فِي أَنْفِهِ، فَقَطَعَهَا النَّبِيُّ صلى الله عليه وسلم بِيَدِهِ وَأَمَرَهُ أَنْ يَقُودَهُ بِيَدِهِ ‏.‏", chapter: "Oaths and Vows (Kitab Al-Aiman Wa Al-Nudhur)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا الأَحْوَصُ بْنُ جَوَّابٍ الضَّبِّيُّ، حَدَّثَنَا عَمَّارُ بْنُ رُزَيْقٍ، عَنْ سُلَيْمَانَ الأَعْمَشِ، عَنِ الْحَكَمِ، عَنْ مِقْسَمٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ صَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم الظُّهْرَ يَوْمَ التَّرْوِيَةِ وَالْفَجْرَ يَوْمَ عَرَفَةَ بِمِنًى ‏.‏", chapter: "The Rites of Hajj (Kitab Al-Manasik Wa'l-Hajj)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو نُعَيْمٍ  ، حَدَّثَنَا عَمْرُو بْنُ عُثْمَانَ  ، قَالَ : سَمِعْتُ مُوسَى بْنَ طَلْحَةَ  يَذْكُرُ، عَنْ حَكِيمِ بْنِ حِزَامٍ  ، قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :\" خَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى، وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ \"", chapter: "مِنْ كِتَابِ الزَّكَاةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا عَيَّاشُ بْنُ الْوَلِيدِ، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ، قَالَ سَأَلْتُ النَّبِيَّ صلى الله عليه وسلم عَنْ قَوْلِهِ ‏{‏وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا‏}‏ قَالَ ‏\"‏ مُسْتَقَرُّهَا تَحْتَ الْعَرْشِ ‏\"‏‏.‏", chapter: "Oneness, Uniqueness of Allah (Tawheed)", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا أَبُو النُّعْمَانِ  ، حَدَّثَنَا هَارُونُ الْأَعْوَرُ  ، عَنْ أَبِي عِمْرَانَ الْجَوْنِيِّ  ، عَنْ جُنْدُبٍ   : أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ :\" اقْرَءُوا الْقُرْآنَ مَا ائْتَلَفْتُمْ عَلَيْهِ، فَإِذَا اخْتَلَفْتُمْ فِيهِ، فَقُومُوا \"", chapter: "وَمِنْ كِتَابِ فَضَائِلِ الْقُرْآنِ", ref: "Darimi · Unknown" },
  { arabic: "وَعَنِ الْبُخَارِيِّ تَعْلِيقًا قَالَ: يَقْرَأُ الْحَسَنُ عَلَى الطِّفْلِ فَاتِحَةَ الْكِتَابِ وَيَقُولُ: اللَّهُمَّ اجْعَلْهُ لَنَا سلفا وفرطا وذخرا وَأَجرا", chapter: "Funerals", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "أخبرنا قَبِيصَةُ ، قَالَ : سَمِعْتُ سُفْيَانَ ، يَقُولُ :\" إِذَا أَقَرَّ لِوَارِثٍ وَلِغَيْرِ وَارِثٍ بِمِائَةِ دِرْهَمٍ، قَالَ : أَرَى أَنْ أُبْطِلَهُمَا جَمِيعًا \"", chapter: "مِنْ كِتَابِ الْوَصَايَا", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللهِ بْنُ مُحَمَّدٍ، قَالَ‏:‏ حَدَّثَنَا أَبُو هَمَّامٍ مُحَمَّدُ بْنُ الزِّبْرِقَانِ، قَالَ‏:‏ حَدَّثَنَا يُونُسُ بْنُ عُبَيْدٍ، عَنِ الْحَسَنِ، عَنِ الأَسْوَدِ بْنِ سَرِيعٍ‏:‏ قُلْتُ‏:‏ يَا رَسُولَ اللهِ، إِنِّي مَدَحْتُ رَبِّي عَزَّ وَجَلَّ بِمَحَامِدَ، قَالَ‏:‏ أَمَا إِنَّ رَبَّكَ يُحِبُّ الْحَمْدَ، وَلَمْ يَزِدْهُ عَلَى ذَلِكَ‏.‏", chapter: "Poetry", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الدِّمَشْقِيُّ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، عَنْ إِبْرَاهِيمَ بْنِ إِسْمَاعِيلَ، عَنْ دَاوُدَ بْنِ الْحُصَيْنِ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ مَنْ وَقَعَ عَلَى ذَاتِ مَحْرَمٍ فَاقْتُلُوهُ وَمَنْ وَقَعَ عَلَى بَهِيمَةٍ فَاقْتُلُوهُ وَاقْتُلُوا الْبَهِيمَةَ ‏\"‏ ‏.‏", chapter: "The Chapters on Legal Punishments", ref: "Ibnmajah · Unknown" },
  { arabic: "وَعَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَا مِنْ غَازِيَة أَو سَرِيَّة تغزو فتغتنم وَتَسْلَمُ إِلَّا كَانُوا قَدْ تَعَجَّلُوا ثُلُثَيْ أُجُورِهِمْ وَمَا مِنْ غَازِيَةٍ أَوْ سَرِيَّةٍ تَخْفُقُ وَتُصَابُ إِلَّا تمّ أُجُورهم» . رَوَاهُ مُسلم", chapter: "Jihad", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَعَنْ عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ: أَنَّهُ دَخَلَ عَلَى عُثْمَانَ وَهُوَ مَحْصُورٌ فَقَالَ: إِنَّكَ إِمَامُ عَامَّةٍ وَنَزَلَ بِكَ مَا تَرَى وَيُصلي لنا إِمَام فتْنَة وننحرج. فَقَالَ: الصَّلَاة أحسن مَا يعْمل النَّاس فَإِذا أحسن النَّاس فَأحْسن مَعَهم وَإِذا أساؤوا فاجتنب إساءتهم. رَوَاهُ البُخَارِيّ", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، وَدَاوُدُ بْنُ شَبِيبٍ، قَالاَ حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ ثَابِتٍ الْبُنَانِيِّ، أَنَّ أَنَسَ بْنَ مَالِكٍ، قَالَ أُقِيمَتْ صَلاَةُ الْعِشَاءِ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي حَاجَةً ‏.‏ فَقَامَ يُنَاجِيهِ حَتَّى نَعَسَ الْقَوْمُ أَوْ بَعْضُ الْقَوْمِ ثُمَّ صَلَّى بِهِمْ وَلَمْ يَذْكُرْ وُضُوءًا ‏.‏", chapter: "Purification (Kitab Al-Taharah)", ref: "Abudawud · Unknown" },
  { arabic: "وَحَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، عَنْ سُلَيْمَانَ بْنِ صُرَدٍ، عَنْ جُبَيْرِ بْنِ مُطْعِمٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّهُ ذُكِرَ عِنْدَهُ الْغُسْلُ مِنَ الْجَنَابَةِ فَقَالَ ‏\n\"‏ أَمَّا أَنَا فَأُفْرِغُ عَلَى رَأْسِي ثَلاَثًا ‏\"‏ ‏.‏", chapter: "The Book of Menstruation", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ يُوسُفَ الْجُبَيْرِيُّ، حَدَّثَنَا أَبُو بَحْرٍ، حَدَّثَنَا سَعِيدُ بْنُ أَبِي عَرُوبَةَ، حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، قَالَ مَا رَأَيْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ أَكَلَ عَلَى خِوَانٍ حَتَّى مَاتَ ‏.‏", chapter: "Chapters on Food", ref: "Ibnmajah · Unknown" },
  { arabic: "عن أسماء بنت يزيد الأنصارية رضى الله عنها قالت‏:‏ كان كم قميص رسول الله صلى الله عليه وسلم إلى الرسغ.‏((رواه أبو داود والترمذي))", chapter: "The Book of Dress", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَحَدَّثَنَاهُ مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا شُعْبَةُ، بِهَذَا الإِسْنَادِ.‏", chapter: "The Book of Zakat", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو الْوَلِيدِ، حَدَّثَنَا شُعْبَةُ، عَنْ أَبِي إِسْحَاقَ، قَالَ سَمِعْتُ الْبَرَاءَ ـ رضى الله عنه ـ يَقُولُ آخِرُ آيَةٍ نَزَلَتْ ‏{‏يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلاَلَةِ‏}‏ وَآخِرُ سُورَةٍ نَزَلَتْ بَرَاءَةٌ‏.‏", chapter: "Prophetic Commentary on the Qur'an (Tafseer of the Prophet (pbuh))", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا الْعَبَّاسُ بْنُ الْوَلِيدِ الدِّمَشْقِيُّ، حَدَّثَنَا مَرْوَانُ بْنُ مُحَمَّدٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، عَنْ دَاوُدَ بْنِ صَالِحٍ الْمَدَنِيِّ، عَنْ أَبِيهِ، قَالَ سَمِعْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ، يَقُولُ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ إِنَّمَا الْبَيْعُ عَنْ تَرَاضٍ ‏\"‏ ‏.‏", chapter: "The Chapters on Business Transactions", ref: "Ibnmajah · Unknown" },
  { arabic: "وَحَدَّثَنِي مَالِكٌ، أَنَّهُ بَلَغَهُ أَنَّ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ، كَانَ يَقُولُ عَلَيْكُمْ بِالصِّدْقِ فَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَالْبِرَّ يَهْدِي إِلَى الْجَنَّةِ وَإِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَالْفُجُورَ يَهْدِي إِلَى النَّارِ أَلاَ تَرَى أَنَّهُ يُقَالُ صَدَقَ وَبَرَّ وَكَذَبَ وَفَجَرَ ‏.‏", chapter: "Speech", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنِي إِسْحَاقُ، أَخْبَرَنَا حَبَّانُ، حَدَّثَنَا هَمَّامٌ، حَدَّثَنَا قَتَادَةُ، حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ ـ رضى الله عنه ـ أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\n\"‏ أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ، فَوَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لأَرَاكُمْ مِنْ بَعْدِ ظَهْرِي إِذَا مَا رَكَعْتُمْ وَإِذَا مَا سَجَدْتُمْ ‏\"‏‏.‏", chapter: "Oaths and Vows", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا سُلَيْمَانُ بْنُ دَاوُدَ، عَنِ ابْنِ وَهْبٍ، قَالَ أَخْبَرَنِي عَمْرٌو، عَنْ بُكَيْرِ بْنِ الأَشَجِّ، عَنْ مُعَاذِ بْنِ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ، عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ ضَحَّيْنَا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم بِجَذَعٍ مِنَ الضَّأْنِ ‏.‏", chapter: "The Book of ad-Dahaya (Sacrifices)", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا صَفْوَانُ بْنُ عِيسَى، عَنِ ابْنِ عَجْلاَنَ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ بِيَدِهِ قَبْلَ أَنْ يَخْلُقَ الْخَلْقَ رَحْمَتِي سَبَقَتْ غَضَبِي ‏\"‏ ‏.‏", chapter: "The Book of the Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُلْ مَا شِئْتَ وَالْبَسْ مَا شِئْتَ مَا أَخْطَأَتْكَ اثْنَتَانِ: سَرَفٌ وَمَخِيلَةٌ. رَوَاهُ الْبُخَارِيُّ فِي تَرْجَمَة بَاب", chapter: "Clothing", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَعَنِ ابْنِ عَبَّاسٍ: أَنَّ رَجُلًا مَاتَ وَلَمْ يَدَعْ وَارِثًا إِلَّا غُلَامًا كَانَ أَعْتَقَهُ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «هَلْ لَهُ أَحَدٌ؟» قَالُوا: لَا إِلَّا غُلَامٌ لَهُ كَانَ أَعْتَقَهُ فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِيرَاثَهُ لَهُ. رَوَاهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَابْنُ مَاجَه", chapter: "Inheritance and Wills", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَحَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ أَبِي الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ لاَ يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلاَ بَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏\"‏ ‏.‏", chapter: "Marriage", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللهِ، قَالَ‏:‏ حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ قَالَ‏:‏ سَمِعْتُ طَلْقَ بْنَ مُعَاوِيَةَ، هُوَ جَدُّهُ، قَالَ‏:‏ سَمِعْتُ أَبَا زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ امْرَأَةً أَتَتِ النَّبِيَّ صلى الله عليه وسلم بِصَبِيٍّ فَقَالَتِ‏:‏ ادْعُ اللَّهَ لَهُ، فَقَدْ دَفَنْتُ ثَلاَثَةً، فَقَالَ‏:‏ احْتَظَرْتِ بِحِظَارٍ شَدِيدٍ مِنَ النَّارِ‏.‏", chapter: "Children's Death", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا عِيسَى بْنُ حَمَّادٍ، أَخْبَرَنَا اللَّيْثُ، عَنْ سَعِيدٍ الْمَقْبُرِيِّ، عَنْ شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ، عَنْ أَنَسٍ، أَنَّهُ سَمِعَهُ يَقُولُ فَذَكَرَ نَحْوَ حَدِيثِ عَبْدِ الْعَزِيزِ قَالَ فَرَفَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَيْهِ بِحِذَاءِ وَجْهِهِ فَقَالَ ‏\n\"‏ اللَّهُمَّ اسْقِنَا ‏\"‏ ‏.‏ وَسَاقَ نَحْوَهُ ‏.‏", chapter: "The Book Of The Prayer For Rain (Kitab al-Istisqa')", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا حَجَّاجٌ، حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ سُئِلَ النَّبِيُّ ـ صلى الله عليه وسلم ـ عَنِ الرَّجُلِ يَغْفُلُ عَنِ الصَّلاَةِ أَوْ يَرْقُدُ عَنْهَا قَالَ ‏\n\"‏ يُصَلِّيهَا إِذَا ذَكَرَهَا ‏\"‏ ‏.‏", chapter: "The Book of the Prayer", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنِ ابْنِ عَجْلاَنَ، عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم نَهَى عَنْ تَنَاشُدِ الأَشْعَارِ فِي الْمَسْجِدِ ‏.‏", chapter: "The Book of the Masjids", ref: "Nasai · Unknown" },
  { arabic: "قَالَ عُرْوَةُ  : وَلَقَدْ حَدَّثَتْنِي عَائِشَةُ  ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ\" يُصَلِّي الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا قَبْلَ أَنْ تَظْهَرَ \"", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "أَخْبَرَنَا أَحْمَدُ بْنُ حَرْبٍ، قَالَ حَدَّثَنَا قَاسِمٌ، قَالَ حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، ‏{‏ عَنِ الشَّعْبِيِّ، ‏}‏ عَنْ جَرِيرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ إِذَا أَبَقَ الْعَبْدُ إِلَى أَرْضِ الشِّرْكِ فَقَدْ حَلَّ دَمُهُ ‏\"‏ ‏.‏", chapter: "The Book of Fighting [The Prohibition of Bloodshed]", ref: "Nasai · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عَفِيفِ بْنِ عَمْرٍو السَّهْمِيِّ، عَنْ عَطَاءِ بْنِ يَسَارٍ، أَنَّهُ قَالَ سَأَلْتُ عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ وَكَعْبَ الأَحْبَارِ عَنِ الَّذِي، يَشُكُّ فِي صَلاَتِهِ فَلاَ يَدْرِي كَمْ صَلَّى أَثَلاَثًا أَمْ أَرْبَعًا فَكِلاَهُمَا قَالَ لِيُصَلِّي رَكْعَةً أُخْرَى ثُمَّ لِيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏.‏", chapter: "Prayer", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا أَصْبَغُ قَالَ‏:‏ أَخْبَرَنِي ابْنُ وَهْبٍ قَالَ‏:‏ أَخْبَرَنِي ابْنُ هَانِئٍ، عَنْ عَمْرِو بْنِ مَالِكٍ، عَنْ فَضَالَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ‏:‏ يُسَلِّمُ الْفَارِسُ عَلَى الْقَاعِدِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ‏.‏", chapter: "Greetings", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ هِشَامٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قُبِضَ النَّبِيُّ صلى الله عليه وسلم وَهُوَ ابْنُ خَمْسٍ وَسِتِّينَ وَهَكَذَا حَدَّثَنَا هُوَ يَعْنِي ابْنَ بَشَّارٍ وَرَوَى عَنْهُ مُحَمَّدُ بْنُ إِسْمَاعِيلَ مِثْلَ ذَلِكَ ‏.‏", chapter: "Chapters on Virtues", ref: "Tirmidhi · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، قَالَ‏:‏ حَدَّثَنَا أَبُو بَكْرٍ، عَنْ نُصَيْرِ بْنِ أَبِي الأَشْعَثِ، عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ سَعِيدٍ قَالَ‏:‏ كَانَ ابْنُ عَبَّاسٍ يَقُولُ‏:‏ اللَّهُمَّ قَنَّعْنِي بِمَا رَزَقْتَنِي، وَبَارِكْ لِي فِيهِ، وَاخْلُفْ عَلَيَّ كُلَّ غَائِبَةٍ بِخَيْرٍ‏.‏", chapter: "Supplication", ref: "Aladab Almufrad · Unknown" },
  { arabic: "وَحَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ، حَدَّثَنَا أَفْلَحُ بْنُ حُمَيْدٍ، عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، عَنْ عَائِشَةَ، - رضى الله عنها - زَوْجِ النَّبِيِّ صلى الله عليه وسلم قَالَتْ طَيَّبْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم بِيَدِي لِحُرْمِهِ حِينَ أَحْرَمَ وَلِحِلِّهِ حِينَ أَحَلَّ قَبْلَ أَنْ يَطُوفَ بِالْبَيْتِ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا ابْنُ أَبِي خَلَفٍ، حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدٍ، حَدَّثَنَا مِسْعَرٌ، عَنْ يَزِيدَ الْفَقِيرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ أَتَتِ النَّبِيَّ صلى الله عليه وسلم بَوَاكِي فَقَالَ ‏\n\"‏ اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعاً نَافِعًا غَيْرَ ضَارٍّ عَاجِلاً غَيْرَ آجِلٍ ‏\"‏ ‏.‏ قَالَ فَأَطْبَقَتْ عَلَيْهِمُ السَّمَاءُ ‏.‏", chapter: "The Book Of The Prayer For Rain (Kitab al-Istisqa')", ref: "Abudawud · Unknown" },
  { arabic: "وَحَدَّثَنَا ابْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ \n أَبِي إِسْحَاقَ، قَالَ قَالَ الْبَرَاءُ أَصَبْنَا يَوْمَ خَيْبَرَ حُمُرًا فَنَادَى مُنَادِي رَسُولِ اللَّهِ صلى الله\n عليه وسلم أَنِ اكْفَئُوا الْقُدُورَ ‏.‏", chapter: "The Book of Hunting, Slaughter, and what may be Eaten", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا حَجَّاجُ بْنُ مِنْهَالٍ  ، حَدَّثَنَا شُعْبَةُ  ، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ  ، عَنْ عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ  ، عَنْ مَحْمُودِ بْنِ لَبِيدٍ  ، عَنْ رَافِعِ بْنِ خَدِيجٍ  ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ :\" أَسْفِرُوا بِصَلَاةِ الصُّبْحِ، فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ \"", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، وَعَبْدُ بْنُ حُمَيْدٍ، قَالَ ابْنُ حَاتِمٍ حَدَّثَنَا مُحَمَّدُ بْنُ بَكْرٍ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، أَخْبَرَنَا أَبُو الزُّبَيْرِ، أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم رَمَى الْجَمْرَةَ بِمِثْلِ حَصَى الْخَذْفِ ‏.‏", chapter: "The Book of Pilgrimage", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنِي أَحْمَدُ بْنُ إِبْرَاهِيمَ الدَّوْرَقِيُّ، قَالَ حَدَّثَنِي عَبْدُ السَّلاَمِ الْوَابِصِيُّ، قَالَ حَدَّثَنِي عَبْدُ اللَّهِ بْنُ جَعْفَرٍ الرَّقِّيُّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ كَانَ يَحْيَى بْنُ أَبِي أُنَيْسَةَ كَذَّابًا ‏.‏", chapter: "Introduction", ref: "Muslim · Unknown" },
  { arabic: "وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: «حَفِظْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وِعَاءَيْنِ فَأَمَّا أَحَدُهُمَا فَبَثَثْتُهُ فِيكُمْ وَأَمَّا الْآخَرُ فَلَوْ بَثَثْتُهُ قُطِعَ هَذَا الْبُلْعُومُ يَعْنِي مجْرى الطَّعَام» رَوَاهُ البُخَارِيّ", chapter: "Knowledge", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَعَلِيُّ بْنُ مُحَمَّدٍ، قَالاَ حَدَّثَنَا وَكِيعٌ، عَنْ سَعِيدِ بْنِ عَبْدِ الْعَزِيزِ، عَنْ سُلَيْمَانَ بْنِ مُوسَى، عَنْ أَبِي سَيَّارَةَ الْمُتَعِيِّ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي نَحْلاً ‏.‏ قَالَ ‏\n\"‏ أَدِّ الْعُشْرَ ‏\"‏ ‏.‏ قُلْتُ يَا رَسُولَ اللَّهِ احْمِهَا لِي ‏.‏ فَحَمَاهَا لِي ‏.‏", chapter: "The Chapters Regarding Zakat", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ هِشَامِ بْنِ حَسَّانَ، عَنْ أَبِي مَعْشَرٍ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، عَنْ عَائِشَةَ، قَالَتْ لَقَدْ رَأَيْتُنِي أَفْرُكُ الْجَنَابَةَ مِنْ ثَوْبِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏", chapter: "The Book of Purification", ref: "Nasai · Unknown" },
  { arabic: "وَعَن الشَّفاءِ بنت عبد الله قَالَتْ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا عِنْدَ حَفْصَةَ فَقَالَ: «أَلَا تُعَلِّمِينَ هَذِهِ رُقْيَةَ النَّمْلَةِ كَمَا عَلَّمْتِيهَا الْكِتَابَةَ؟» . رَوَاهُ أَبُو دَاوُد", chapter: "Medicine and Spells", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، حَدَّثَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ أَبِي الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ ‏\n\"‏ إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏\"‏ ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "وَحَدَّثَنِيهِ زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، - يَعْنِي ابْنَ مَهْدِيٍّ - عَنْ مَالِكِ، بْنِ أَنَسٍ بِهَذَا الإِسْنَادِ وَزَادَ ‏\n\"‏ لاَ تَبْتَعْهُ وَإِنْ أَعْطَاكَهُ بِدِرْهَمٍ ‏\"‏ ‏.‏", chapter: "The Book of Gifts", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، بِهَذَا الْحَدِيثِ قَالَ فَكَشَفُوا عَانَتِي فَوَجَدُوهَا لَمْ تَنْبُتْ فَجَعَلُونِي فِي السَّبْىِ ‏.‏", chapter: "Prescribed Punishments (Kitab Al-Hudud)", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا سَعِيدُ بْنُ أَبِي مَرْيَمَ، حَدَّثَنَا سُلَيْمَانُ بْنُ بِلاَلٍ، قَالَ أَخْبَرَنِي مُعَاوِيَةُ بْنُ أَبِي مُزَرِّدٍ، عَنْ يَزِيدَ بْنِ رُومَانَ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ زَوْجِ النَّبِيِّ صلى الله عليه وسلم عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ الرَّحِمُ شِجْنَةٌ، فَمَنْ وَصَلَهَا وَصَلْتُهُ، وَمَنْ قَطَعَهَا قَطَعْتُهُ ‏\"‏‏.‏", chapter: "Good Manners and Form (Al-Adab)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ رُمْحٍ الْمِصْرِيُّ، أَنْبَأَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنْ إِسْحَاقَ بْنِ أَبِي فَرْوَةَ، عَنِ ابْنِ شِهَابٍ، عَنْ حُمَيْدٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ الْقَاتِلُ لاَ يَرِثُ ‏\"‏ ‏.‏", chapter: "The Chapters on Blood Money", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ، أَخْبَرَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، وَعَمْرِو بْنِ دِينَارٍ، وَعَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ أَكَلَ النَّبِيُّ ـ صلى الله عليه وسلم ـ وَأَبُو بَكْرٍ وَعُمَرُ خُبْزًا وَلَحْمًا وَلَمْ يَتَوَضَّئُوا ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏ رغم أنف، ثم رغم أنف، ثم رغم أنف من أدرك أبويه عند الكبر، أحدهما أو كليهما، فلم يدخل الجنة‏\"‏  ((رواه مسلم))", chapter: "The Book of Miscellany", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وعن أبي هريرة رضي الله عنه ‏:‏ قال‏:‏ قال رسول الله صلى الله عليه وسلم قاربوا وسددوا، واعلموا أنه لن ينجو أحد منكم بعمله‏\"‏ قالوا‏:‏ ولا أنت يا رسول الله ‏؟‏ قال‏:‏ ‏\"‏ولا أنا إلا أن يتغمدنى الله برحمة منه وفضل‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏", chapter: "The Book of Miscellany", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنَا رَبِيعُ بْنُ يَحْيَى، قَالَ حَدَّثَنَا زَائِدَةُ، عَنْ هِشَامٍ، عَنْ فَاطِمَةَ، عَنْ أَسْمَاءَ، قَالَتْ لَقَدْ أَمَرَ النَّبِيُّ صلى الله عليه وسلم بِالْعَتَاقَةِ فِي كُسُوفِ الشَّمْسِ‏.‏", chapter: "Eclipses", ref: "Buhari · Unknown" },
  { arabic: "وَسُئِلَ أَن بْنُ مَالِكٍ عَنِ الْقُنُوتِ. فَقَالَ: قَنَتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدُ الرُّكُوعِ وَفِي رِوَايَةٍ: قَبْلَ الرُّكُوعِ وَبَعْدَهُ. رَوَاهُ ابْنُ مَاجَهْ", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا النَّضْرُ بْنُ شُمَيْلٍ، حَدَّثَنَا هِشَامٌ، عَنْ يَحْيَى، بْنِ أَبِي كَثِيرٍ حَدَّثَنِي إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ، عَنِ السَّائِبِ بْنِ يَزِيدَ، حَدَّثَنَا رَافِعُ بْنُ خَدِيجٍ، عَنْ  رَسُولِ اللَّهِ صلى الله عليه وسلم بِمِثْلِهِ ‏.‏", chapter: "The Book of Musaqah", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ رُمْحٍ، أَنْبَأَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنْ يَزِيدَ بْنِ أَبِي حَبِيبٍ، عَنْ أَبِي الْخَيْرِ، عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ أَعْطَاهُ غَنَمًا فَقَسَمَهَا عَلَى أَصْحَابِهِ ضَحَايَا فَبَقِيَ عَتُودٌ فَذَكَرَهُ لِرَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَقَالَ ‏\n\"‏ ضَحِّ بِهِ أَنْتَ ‏\"‏ ‏.‏", chapter: "Chapters on Sacrifices", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ عُيَيْنَةَ  ، أَخْبَرَنَا عَلِيٌّ هُوَ ابْنُ مُسْهِرٍ  ، عَنْ أَبِي إِسْحَاق  ، عَنْ الشَّعْبِيِّ  ، عَنْ زِيَادِ بْنِ حُدَيْرٍ  ، قَالَ : قَالَ لِي عُمَرُ   : هَلْ تَعْرِفُ مَا يَهْدِمُ الْإِسْلَامَ؟، قُلْتُ : لَا، قَالَ :\" يَهْدِمُهُ زَلَّةُ الْعَالِمِ، وَجِدَالُ الْمُنَافِقِ بِالْكِتَابِ، وَحُكْمُ الْأَئِمَّةِ الْمُضِلِّينَ \"", chapter: "سنن الدارمي", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا حَجَّاجُ بْنُ مِنْهَالٍ  ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ  ، عَنْ ثَابِتٍ  ، عَنْ أَنَسٍ   : أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ\" يُغِيرُ عِنْدَ صَلَاةِ الْفَجْرِ، وَكَانَ يَسْتَمِعُ، فَإِنْ سَمِعَ أَذَانًا، أَمْسَكَ، وَإِنْ لَمْ يَسْمَعْ أَذَانًا، أَغَارَ \"", chapter: "وَمِنْ كِتَابِ السِّيَرِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا يَحْيَى بْنُ مُحَمَّدٍ الْجَارِيُّ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، عَنْ مَالِكٍ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم غَابَتْ لَهُ الشَّمْسُ بِمَكَّةَ فَجَمَعَ بَيْنَهُمَا بِسَرِفَ ‏.‏", chapter: "Prayer (Kitab Al-Salat): Detailed Rules of Law about the Prayer during Journey", ref: "Abudawud · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو الْخَطَّابِ زِيَادُ بْنُ يَحْيَى، قَالَ‏:‏ حَدَّثَنَا عَبْدُ اللهِ بْنُ مَيْمُونٍ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرِ بْنِ عَبْدِ اللهِ‏:‏ أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَتَخَتَّمُ فِي يَمِينِهِ‏.‏", chapter: "Stating That Rasoolullah Wore The Ring On His Right Hand", ref: "Shamail Muhammadiyah · Unknown" },
  { arabic: "حَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ يَزِيدَ بْنِ كَيْسَانَ، حَدَّثَنِي أَبُو\n حَازِمٍ قَالَ رَأَيْتُ أَبَا هُرَيْرَةَ يُشِيرُ بِإِصْبَعِهِ مِرَارًا يَقُولُ وَالَّذِي نَفْسُ أَبِي هُرَيْرَةَ بِيَدِهِ مَا\n شَبِعَ نَبِيُّ اللَّهِ صلى الله عليه وسلم وَأَهْلُهُ ثَلاَثَةَ أَيَّامٍ تِبَاعًا مِنْ خُبْزِ حِنْطَةٍ حَتَّى فَارَقَ\n الدُّنْيَا ‏.‏", chapter: "The Book of Zuhd and Softening of Hearts", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا سُلَيْمَانُ بْنُ حَرْبٍ ، عَنْ عُمَارَةَ بْنِ مِهْرَانَ ، عَنْ الْحَسَنِ ، قَالَ :\" أَدْرَكْتُ النَّاسَ وَالنَّاسِكُ إِذَا نَسَكَ لَمْ يُعْرَفْ مِنْ قِبَلِ مَنْطِقِهِ، وَلَكِنْ يُعْرَفُ مِنْ قِبَلِ عَمَلِهِ، فَذَلِكَ الْعِلْمُ النَّافِعُ \"", chapter: "سنن الدارمي", ref: "Darimi · Unknown" },
  { arabic: "أَخْبَرَنَا مَحْمُودُ بْنُ غَيْلاَنَ الْمَرْوَزِيُّ، قَالَ حَدَّثَنَا وَكِيعٌ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنْ عَاصِمِ بْنِ كُلَيْبٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الأَسْوَدِ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، أَنَّهُ قَالَ أَلاَ أُصَلِّي بِكُمْ صَلاَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَصَلَّى فَلَمْ يَرْفَعْ يَدَيْهِ إِلاَّ مَرَّةً وَاحِدَةً ‏.‏", chapter: "The Book of The At-Tatbiq (Clasping One's Hands Together)", ref: "Nasai · Unknown" },
  { arabic: "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ السَّلَمِيِّ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم نَهَى أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ أَوْ يَمْشِيَ فِي نَعْلٍ وَاحِدَةٍ وَأَنْ يَشْتَمِلَ الصَّمَّاءَ وَأَنْ يَحْتَبِيَ فِي ثَوْبٍ وَاحِدٍ كَاشِفًا عَنْ فَرْجِهِ ‏.‏", chapter: "The Description of the Prophet, may Allah Bless Him and Grant Him Peace", ref: "Malik · Unknown" },
  { arabic: "وعن عقبة بن عامر  أن رسول الله صلى الله عليه وسلم  قال‏:‏ ‏\n\"‏المؤمن أخو المؤمن، فلا يحل لمؤمن أن يبتاع على بيع أخيه ولا يخطب على خطبة أخيه حتى يذر‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا أَحْمَدُ بْنُ إِسْحَاقَ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ مُغِيرَةَ،\n عَنْ عَامِرٍ، عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ أَتَيْتُ عُمَرَ بْنَ الْخَطَّابِ فَقَالَ لِي إِنَّ أَوَّلَ صَدَقَةٍ بَيَّضَتْ\n وَجْهَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَوُجُوهَ أَصْحَابِهِ صَدَقَةُ طَيِّئٍ جِئْتَ بِهَا إِلَى رَسُولِ\n اللَّهِ صلى الله عليه وسلم ‏.‏", chapter: "The Book of the Merits of the Companions", ref: "Muslim · Unknown" },
  { arabic: "وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\"‏من أمسك كلبًا فإنه ينقص كل يوم من عمله قيراط إلا كلب حرث أو ماشية‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏  \nوفي رواية لمسلم‏:‏ ‏\"‏من اقتنى كلبًا ليس بكلب صيد، ولا ماشية ولا أرض، فإنه ينقص من أجره قيراطان كل يوم‏\"‏‏.‏", chapter: "The Book of the Prohibited actions", ref: "Riyad Assalihin · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُعَاوِيَةَ الْجُمَحِيُّ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ سَعِيدِ بْنِ جُمْهَانَ، عَنْ سَفِينَةَ أَبِي عَبْدِ الرَّحْمَنِ، قَالَ أَعْتَقَتْنِي أُمُّ سَلَمَةَ وَاشْتَرَطَتْ عَلَىَّ أَنْ أَخْدُمَ النَّبِيَّ صلى الله عليه وسلم مَا عَاشَ ‏.‏", chapter: "The Chapters on Manumission (of Slaves)", ref: "Ibnmajah · Unknown" },
  { arabic: "وعن أبى هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ “لا ينظر الله يوم القيامة إلى من جر إزاره بطراً” ‏(‏‏(‏متفق عليه‏)‏‏)‏", chapter: "The Book of Miscellany", ref: "Riyad Assalihin · Unknown" },
  { arabic: "وَحَدَّثَنِي حَجَّاجُ بْنُ الشَّاعِرِ، حَدَّثَنَا مُعَلَّى بْنُ أَسَدٍ، حَدَّثَنَا وُهَيْبُ بْنُ خَالِدٍ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ أَبِي مُرَّةَ، مَوْلَى عَقِيلٍ عَنْ أُمِّ هَانِئٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم صَلَّى فِي بَيْتِهَا عَامَ الْفَتْحِ ثَمَانِيَ رَكَعَاتٍ فِي ثَوْبٍ وَاحِدٍ قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ ‏.‏", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "وَعَنِ ابْنِ عُمَرَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «لَعَنَ اللَّهُ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ والواشمة والمستوشمة»", chapter: "Clothing", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "حَدَّثَنَا عَمْرُو بْنُ حَمَّادٍ ، حَدَّثَنَا قَزَعَةُ بْنُ سُوَيْدٍ ، عَنْ حُمَيْدٍ الْأَعْرَجِ ، قَالَ :\" مَنْ قَرَأَ الْقُرْآنَ ثُمَّ دَعَا، أَمَّنَ عَلَى دُعَائِهِ أَرْبَعَةُ آلَافِ مَلَكٍ \"", chapter: "وَمِنْ كِتَابِ فَضَائِلِ الْقُرْآنِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، أَنْبَأَنَا إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، قَالَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فِي سَفَرٍ وَكَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ لاَ يَأْتِي الْبَرَازَ حَتَّى يَتَغَيَّبَ فَلاَ يُرَى ‏.‏", chapter: "The Book of Purification and its Sunnah", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنِ الأَجْلَحِ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِي الأَسْوَدِ الدِّيلِيِّ، عَنْ أَبِي ذَرٍّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ إِنَّ أَحْسَنَ مَا غَيَّرْتُمْ بِهِ الشَّيْبَ الْحِنَّاءُ وَالْكَتَمُ ‏\"‏ ‏.‏", chapter: "The Book of Adornment", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللهِ بْنُ أَبِي الأَسْوَدِ، قَالَ‏:‏ حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ قَالَ‏:‏ أَصَابَنَا مَعَ النَّبِيِّ صلى الله عليه وسلم مَطَرٌ، فَحَسَرَ النَّبِيُّ صلى الله عليه وسلم ثَوْبَهُ عَنْهُ حَتَّى أَصَابَهُ الْمَطَرُ، قُلْنَا‏:‏ لِمَ فَعَلْتَ‏؟‏ قَالَ‏:‏ لأَنَّهُ حَدِيثُ عَهْدٍ بِرَبِّهِ‏.‏", chapter: "General Behavior", ref: "Aladab Almufrad · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ مَسْعُودٍ الْمِصِّيصِيُّ، حَدَّثَنَا عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ، حَدَّثَنَا مُحَمَّدُ بْنُ دِينَارٍ، حَدَّثَنَا سَعْدُ بْنُ أَوْسٍ، عَنْ مِصْدَعٍ أَبِي يَحْيَى، قَالَ سَمِعْتُ ابْنَ عَبَّاسٍ، يَقُولُ أَقْرَأَنِي أُبَىُّ بْنُ كَعْبٍ كَمَا أَقْرَأَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏{‏ فِي عَيْنٍ حَمِئَةٍ ‏}‏ مُخَفَّفَةً ‏.‏", chapter: "Dialects and Readings of the Qur'an (Kitab Al-Huruf Wa Al-Qira'at)", ref: "Abudawud · Unknown" },
  { arabic: "أَخْبَرَنَا أَبُو مَعْمَرٍ ، عَنْ هُشَيْمٍ ، أَخْبَرَنَا يُونُسُ ، قَالَ :\" كُنَّا نَأْتِي الْحَسَنَ، فَإِذَا خَرَجْنَا مِنْ عِنْدِهِ، تَذَاكَرْنَا بَيْنَنَا \"", chapter: "سنن الدارمي", ref: "Darimi · Unknown" },
  { arabic: "وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، ح وَحَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا هَمَّامٌ، جَمِيعًا عَنْ قَتَادَةَ، بِهَذَا الإِسْنَادِ قَالَ شُعْبَةُ مِنْ آخِرِ الْكَهْفِ ‏.‏ وَقَالَ هَمَّامٌ مِنْ أَوَّلِ الْكَهْفِ كَمَا قَالَ هِشَامٌ.", chapter: "The Book of Prayer - Travellers", ref: "Muslim · Unknown" },
  { arabic: "وَحَدَّثَنَاهُ قُتَيْبَةُ، وَابْنُ، رُمْحٍ عَنِ اللَّيْثِ بْنِ سَعْدٍ، ح وَحَدَّثَنَا ابْنُ رَافِعٍ، حَدَّثَنَا ابْنُ،\n أَبِي فُدَيْكٍ أَخْبَرَنَا الضَّحَّاكُ، - يَعْنِي ابْنَ عُثْمَانَ - كِلاَهُمَا عَنْ نَافِعٍ، بِهَذَا الإِسْنَادِ وَفِي\n حَدِيثِ اللَّيْثِ قَالَ نَافِعٌ حَسِبْتُ أَنَّ ابْنَ عُمَرَ قَالَ ‏\n\"‏ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنَ النُّبُوَّةِ ‏\"‏\n ‏.‏", chapter: "The Book of Dreams", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، عَنْ أَسْلَمَ الْمِنْقَرِيِّ، عَنْ عَبْدِ اللَّهِ، عَنْ أَبِيهِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى، قَالَ قَالَ أُبَىُّ بْنُ كَعْبٍ ‏{‏ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْتَفْرَحُوا ‏}‏ ‏.‏ قَالَ أَبُو دَاوُدَ بِالتَّاءِ ‏.‏", chapter: "Dialects and Readings of the Qur'an (Kitab Al-Huruf Wa Al-Qira'at)", ref: "Abudawud · Unknown" },
  { arabic: "وَحَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدٍ الْغُبَرِيُّ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، تَزَوَّجَ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم عَلَى وَزْنِ نَوَاةٍ مِنْ ذَهَبٍ ‏.‏ فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ أَوْلِمْ وَلَوْ بِشَاةٍ ‏\"‏.", chapter: "The Book of Marriage", ref: "Muslim · Unknown" },
  { arabic: "أَخْبَرَنَا سُوَيْدٌ، قَالَ أَنْبَأَنَا عَبْدُ اللَّهِ، عَنْ هِشَامِ بْنِ عَائِذٍ الأَسَدِيِّ، قَالَ سَأَلْتُ إِبْرَاهِيمَ عَنِ الْعَصِيرِ، قَالَ اشْرَبْهُ حَتَّى يَغْلِيَ مَا لَمْ يَتَغَيَّرْ ‏.‏", chapter: "The Book of Drinks", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنِي إِبْرَاهِيمُ بْنُ مُوسَى، أَخْبَرَنَا هِشَامٌ، أَنَّ ابْنَ جُرَيْجٍ، أَخْبَرَهُمْ قَالَ أَخْبَرَنِي عَبْدُ الْكَرِيمِ، أَنَّهُ سَمِعَ مِقْسَمًا، مَوْلَى عَبْدِ اللَّهِ بْنِ الْحَارِثِ يُحَدِّثُ عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ سَمِعَهُ يَقُولُ ‏{‏لاَ يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ‏}‏ عَنْ بَدْرٍ، وَالْخَارِجُونَ، إِلَى بَدْرٍ‏.‏", chapter: "Military Expeditions led by the Prophet (pbuh) (Al-Maghaazi)", ref: "Buhari · Unknown" },
  { arabic: "أَخْبَرَنَا عَبْدُ الْجَبَّارِ بْنُ الْعَلاَءِ، عَنْ سُفْيَانَ، قَالَ حَدَّثَنَا الزُّهْرِيُّ، عَنْ سَالِمٍ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\n\"‏ مَنِ اقْتَنَى كَلْبًا إِلاَّ كَلْبَ صَيْدٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطَانِ ‏\"‏ ‏.‏", chapter: "The Book of Hunting and Slaughtering", ref: "Nasai · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ الْمُصَفَّى، حَدَّثَنَا بَقِيَّةُ، قَالَ حَدَّثَنِي عُمَرُ بْنُ جُعْثُمَ الْقُرَشِيُّ، قَالَ حَدَّثَنِي زَيْدُ بْنُ أَبِي أُنَيْسَةَ، عَنْ عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ مُسْلِمِ بْنِ يَسَارٍ، عَنْ نُعَيْمِ بْنِ رَبِيعَةَ، قَالَ كُنْتُ عِنْدَ عُمَرَ بْنِ الْخَطَّابِ بِهَذَا الْحَدِيثِ وَحَدِيثُ مَالِكٍ أَتَمُّ ‏.‏", chapter: "Model Behavior of the Prophet (Kitab Al-Sunnah)", ref: "Abudawud · Unknown" },
  { arabic: "وَعَن أبي حجيفة أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الدَّمِ وَثَمَنِ الْكَلْبِ وَكَسْبِ الْبَغِيِّ وَلَعَنَ آكِلَ الرِّبَا وَمُوكِلَهُ وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ وَالْمُصَوِّرَ. رَوَاهُ البُخَارِيّ", chapter: "Business Transactions", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَعَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ النَّاسَ لَكُمْ تَبَعٌ وَإِنَّ رِجَالًا يَأْتُونَكُمْ مِنْ أَقْطَارِ الْأَرْضِ يَتَفَقَّهُونَ فِي الدِّينِ فَإِذَا أَتَوْكُمْ فَاسْتَوْصُوا بهم خيرا» . رَوَاهُ التِّرْمِذِيّ", chapter: "Knowledge", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَعَنْ أَبِي هُرَيْرَةَ ‏- رضى الله عنه ‏- { أَنَّ اَلنَّبِيَّ ‏- صلى الله عليه وسلم ‏-نَعَى اَلنَّجَاشِيَّ فِي اَلْيَوْمِ اَلَّذِي مَاتَ فِيهِ, وَخَرَجَ بِهِمْ مِنَ الْمُصَلَّى، فَصَفَّ بِهِمْ, وَكَبَّرَ عَلَيْهِ أَرْبَعًا }  مُتَّفَقٌ عَلَيْهِ  1‏ .‏‏1 ‏- صحيح.‏ رواه البخاري (1245)‏، ومسلم (951)‏ (62)‏.‏", chapter: "Funerals", ref: "Bulugh Almaram · Unknown" },
  { arabic: "حَدَّثَنَا عُبَيْدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ مَا غِرْتُ عَلَى امْرَأَةٍ مَا غِرْتُ عَلَى خَدِيجَةَ، وَلَقَدْ أَمَرَهُ رَبُّهُ أَنْ يُبَشِّرَهَا بِبَيْتٍ فِي الْجَنَّةِ‏.‏", chapter: "Oneness, Uniqueness of Allah (Tawheed)", ref: "Buhari · Unknown" },
  { arabic: "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كَانَ يُنْبَذُ لِرَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فِي تَوْرٍ مِنْ حِجَارَةٍ ‏.‏", chapter: "Chapters on Drinks", ref: "Ibnmajah · Unknown" },
  { arabic: "حَدَّثَنَا عُبَيْدُ اللهِ، عَنِ مُبَارَكِ بْنِ حَسَّانَ، عَنْ عَطَاءٍ، عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ‏:‏ سُئِلَ النَّبِيُّ صلى الله عليه وسلم‏:‏ أَيُّ الْعِبَادَةِ أَفْضَلُ‏؟‏ قَالَ‏:‏ دُعَاءُ الْمَرْءِ لِنَفْسِهِ‏.‏", chapter: "Supplication", ref: "Aladab Almufrad · Unknown" },
  { arabic: "أَخْبَرَنَا أَبُو الْوَلِيدِ الطَّيَالِسِيُّ  ، أَخْبَرَنَا أَبُو خَيْثَمَةَ  ، حَدَّثَنَا أَبُو إِسْحَاقَ  ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ  ، عَنْ أَبِيهِ  ، وَعَنْ عَلْقَمَةَ  ، عَنْ عَبْدِ اللَّهِ  ، قَالَ : رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ\" يُكَبِّرُ فِي كُلِّ رَفْعٍ وَوَضْعٍ، وَقِيَامٍ، وَقُعُودٍ \"", chapter: "كِتَاب الصَّلَاةِ", ref: "Darimi · Unknown" },
  { arabic: "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ أَنَسَ بْنَ مَالِكٍ، كَبِرَ حَتَّى كَانَ لاَ يَقْدِرُ عَلَى الصِّيَامِ فَكَانَ يَفْتَدِي ‏.‏ قَالَ مَالِكٌ وَلاَ أَرَى ذَلِكَ وَاجِبًا وَأَحَبُّ إِلَىَّ أَنْ يَفْعَلَهُ إِذَا كَانَ قَوِيًّا عَلَيْهِ فَمَنْ فَدَى فَإِنَّمَا يُطْعِمُ مَكَانَ كُلِّ يَوْمٍ مُدًّا بِمُدِّ النَّبِيِّ صلى الله عليه وسلم ‏.‏", chapter: "Fasting", ref: "Malik · Unknown" },
  { arabic: "حَدَّثَنَا أَحْمَدُ بْنُ أَبِي الْحَوَارِيِّ الدِّمَشْقِيُّ، حَدَّثَنَا مَرْوَانُ بْنُ مُحَمَّدٍ، حَدَّثَنَا سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\n\"‏ بَيْتٌ لاَ تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ ‏\"‏ ‏.‏", chapter: "Chapters on Food", ref: "Ibnmajah · Unknown" },
  { arabic: "أَخْبَرَنَا مُحَمَّدُ بْنُ عِيسَى ، عَنْ رَوْحٍ ، عَنْ ابْنِ جُرَيْجٍ ، عَنْ عَطَاءٍ ، وَابْنِ جُرَيْجٍ ، عَنْ ابْنِ طَاوُسٍ ، عَنْ أَبِيهِ ، قَالَ :\" الْوَلَاءُ لِلْكُبْرِ \"", chapter: "مِنْ كِتَابِ الْفَرَائِضِ", ref: "Darimi · Unknown" },
  { arabic: "وَحَدَّثَنِي أَحْمَدُ بْنُ سَعِيدٍ الدَّارِمِيُّ، حَدَّثَنَا حَبَّانُ بْنُ هِلاَلٍ، حَدَّثَنَا أَبَانُ الْعَطَّارُ، حَدَّثَنَا غَيْلاَنُ بْنُ جَرِيرٍ، فِي هَذَا الإِسْنَادِ بِمِثْلِ حَدِيثِ شُعْبَةَ غَيْرَ أَنَّهُ ذَكَرَ فِيهِ الاِثْنَيْنِ وَلَمْ يَذْكُرِ الْخَمِيسَ ‏.‏", chapter: "The Book of Fasting", ref: "Muslim · Unknown" },
  { arabic: "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ، عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\"‏ لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثَةِ أَيَّامٍ يَلْتَقِيَانِ فَيُعْرِضُ هَذَا وَيُعْرِضُ هَذَا وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلاَمِ ‏\"‏ ‏.‏", chapter: "General Behavior (Kitab Al-Adab)", ref: "Abudawud · Unknown" },
  { arabic: "أَخْبَرَنَا الْوَلِيدُ بْنُ شُجَاعٍ ، حَدَّثَنِي مُحَمَّدُ بْنُ شُعَيْبِ بْنِ شَابُورٍ ، أَخْبَرَنَا الْوَلِيدُ بْنُ سُلَيْمَانَ بْنِ أَبِي السَّائِبِ ، عَنْ رَجَاءِ بْنِ حَيْوَةَ ، أَنَّهُ حَدَّثَهُ، قَالَ : كَتَبَ هِشَامُ بْنُ عَبْدِ الْمَلِكِ إِلَى عَامِلِهِ أَنْ يَسْأَلَنِي عَنْ حَدِيثٍ، قَالَ رَجَاءٌ :\" فَكُنْتُ قَدْ نَسِيتُهُ لَوْلَا أَنَّهُ كَانَ عِنْدِي مَكْتُوبًا \"", chapter: "سنن الدارمي", ref: "Darimi · Unknown" },
  { arabic: "وَعَنْ عَبْدِ اللَّهِ بْنِ السَّائِبِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسلم يُصَلِّي أَرْبَعًا بَعْدَ أَنْ تَزُولَ الشَّمْسُ قَبْلَ الظُّهْرِ وَقَالَ: «إِنَّهَا سَاعَةٌ تُفْتَحُ فِيهَا أَبْوَابُ السَّمَاءِ فَأُحِبُّ أَنْ يَصْعَدَ لِي فِيهَا عَمَلٌ صَالِحٌ» . رَوَاهُ التِّرْمِذِيّ", chapter: "Prayer", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "وَعَن جَابر قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلَابِ حَتَّى إِنَّ الْمَرْأَةَ تَقْدَمُ منَ البادِيةِ بكلبِها فتقتلَه ثُمَّ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا وَقَالَ: «عَلَيْكُمْ بِالْأَسْوَدِ الْبَهِيمِ ذِي النقطتين فَإِنَّهُ شَيْطَان» . رَوَاهُ مُسلم", chapter: "Game and Animals Which May Be Slaughtered", ref: "Mishkat Almasabih · Unknown" },
  { arabic: "عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : \n\" أتاكم رمضان شهر مبارك فرض الله عليكم صيامه تفتح فيه أبواب السماء وتغلق فيه أبواب الجحيم وتغل فيه مردة الشياطين لله فيه ليلة خير من ألف شهر من حرم خيرها فقد حرم \" . رواه أحمد والنسائي", chapter: "Fasting", ref: "Mishkat Almasabih · Unknown" },
];
